programs.haiku:
"""Relative-clause introducers: a relative pronoun ("that", "which", "who", "where", "whose")
that follows a noun opens a clause describing that noun. The model's MLP fires on these
(and, more weakly, on participles like "containing", "having" that start a similar
modifier); it stays quiet on the demonstrative "that" ("do that", "in that case"),
on "that" after verbs of saying or knowing ("shows that", "seems that"), which open a
complement clause, and on a sentence-initial "Which" or "That", which asks or points."""

READS = ()

WH = {"which", "who", "whom", "whose", "where"}
SENTENCE_START = {".", "?", "!", "\n", ":", ""}
# prepositions and verbs/function words after which "that" is a demonstrative or conjunction
DEMO_PREV = {"do", "does", "did", "to", "than", "is", "of", "on", "in", "for", "at", "from",
             "by", "after", "before", "during", "throughout", "but", "and", "all", "like", "with",
             "as", "given", "since", "if", "so", "out", "see", "seems", "seem", "implies", "imply",
             "means", "mean", "learn", "remember", "observe", "emphasize", "noting", "wonder"}
# verbs of saying, showing or knowing: "shows that", "found that", "suggest that"
CLAUSE_VERBS = {"show", "shows", "showed", "shown", "found", "find", "ensure", "suggest", "suggests",
                "say", "says", "said", "know", "knew", "think", "believe", "note", "noted", "notes",
                "indicate", "indicated", "confirm", "confirms", "verify", "prove", "stated", "states",
                "state", "concluded", "reveal", "revealed", "results", "assume", "hope", "feel",
                "realize", "claims", "claim", "mentioned", "reported", "expect"}
# participles that start a modifier after a noun: "a tool containing ...", "a device having ..."
PARTICIPLES = {"containing", "having", "including", "such", "involving", "described", "specified",
               "designed", "using", "featuring", "comprising", "consisting", "corresponding"}

def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    w = prefix.token_strings[-1].strip().lower()
    same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if w in WH:
        if prev in SENTENCE_START:
            return None, -0.3
        if prev == ",":
            return None, 0.8   # non-restrictive: ", which ..."
        return None, 2.3
    if w == "that":
        if prev in SENTENCE_START:
            return None, -0.3
        if prev == ",":
            return None, 0.8
        if prev in DEMO_PREV:
            return None, -0.3
        if prev in CLAUSE_VERBS:
            return None, 0.4
        return None, 2.3
    if w in PARTICIPLES:
        return None, 0.5
    return None, 0.0

programs.luna:
"""Approximate a relative-clause cue using only the current word.

The largest responses are on words that link or introduce a clause, such as
"that", "which", and "who". A few equivalents in other languages and "such"
receive smaller scores. Some capitalized spellings get separate scores.
"""

READS = ()

RELATIVES = {
    "that": 1.69, "which": 1.61, "who": 1.71,
    "whose": 2.35, "whom": 0.79, "where": 1.72,
    "qui": 1.17, "que": 0.67, "où": 1.26,
    "которые": 0.77, "который": 0.96, "где": 0.58,
    "التي": 3.18, "yang": 0.57, "wherein": 0.77,
}

INITIAL = {
    "That": 0.75, "Which": -0.24, "Who": 0.18, "Where": 0.57,
    "THAT": 2.26, "WHERE": 1.13,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in INITIAL:
        value = INITIAL[word]
    elif word.lower() == "such":
        value = 0.32
    else:
        value = RELATIVES.get(word.lower(), 0.0)
    return None, float(value)

programs.sol:
"""A lexical approximation, not a single semantic detector.

Congress is the strongest negative trigger. God and the fragment 'py' are
weaker ones. Conversation markup, long blank lines, and underscore separators
also respond. Markup has a document-initial transient that fades as context
grows. Only document age and the previous word are kept. Most tokens get a
near-zero baseline, leaving much background activation unexplained.
"""
import math

READS = ()

# Markup: long-context value, initial-context correction, decay length,
# and value when the marker itself starts a document.
MARKUP = {
    '<|im_start|>': (-0.015, 1.63, 9.8, 0.377),
    '<|im_end|>': (-0.004, 1.05, 3.5, 0.279),
    '<|endoftext|>': (0.018, -2.90, 30.0, -0.134),
    '<think>': (-0.056, 2.82, 16.3, 0.380),
    '</think>': (-0.256, 2.53, 14.3, 0.215),
    '<tool_call>': (-0.119, 1.31, 15.8, 0.304),
    '</tool_call>': (0.009, 0.77, 3.0, 0.267),
    '<tool_response>': (-0.093, 2.24, 14.3, 0.331),
    '</tool_response>': (0.030, 1.39, 7.8, 0.367),
}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        age, previous = 0, ''
    else:
        age, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0015

    if token in MARKUP:
        base, correction, scale, initial = MARKUP[token]
        value = initial if age == 0 else base + correction / (age + scale)
    elif previous == '<|im_start|>' and word == 'user':
        value = -0.009 + 0.431 / (age + 1.5)
    elif previous == '<|im_start|>' and word == 'assistant':
        value = 0.004 + 0.165 * math.exp(-age / 2)
    elif previous == '<|im_start|>' and word == 'system':
        value = 0.284 if age == 1 else 0.01
    elif word == 'Congress':
        value = -0.51 if token.startswith(' ') else -0.34
        if previous.lower() == 'the':
            value -= 0.10
    elif word == 'congress':
        value = -0.40
    elif word.lower() in {'congressman', 'congressional'}:
        value = -0.14 if word.islower() or word == 'Congressman' else -0.07
    elif word in {'God', 'god', 'gods', 'Gods', 'GOD'}:
        value = -0.28 if word == 'God' else -0.18
    elif word in {'py', 'Py', '.py', '/py'}:
        value = -0.153 if word == '.py' else -0.13
    elif token == '.js':
        value = -0.077
    elif token.count('\n') >= 4:
        value = -0.40 if token.count('\n') == 5 else -0.13
    elif len(word) >= 24 and set(word) == {'_'}:
        value = -0.19 if len(word) >= 64 else -0.13

    return (doc, age, word), value

"""A sparse utilization-expression detector.

The largest response is 'the' immediately after 'use' or 'using'.
Other complements of use-family verbs, related application/employment words,
and selected utilization words or stems in other languages respond less.
Weak article-context rules distinguish instrumental/possession frames from
relative, restrictive, or spatial frames. Only the preceding token is
remembered, and it is discarded at document boundaries.

This approximates the interpretable peaks, not the remaining lexical
background. An unrelated token generally receives zero.
"""

READS = ()

USE_FORMS = {'use': 1.0, 'using': 0.93, 'uses': 0.86, 'used': 0.69}
USE_COMPLEMENTS = {
    'the': 1.41, 'of': 0.95, 'this': 0.56, 'these': 0.44,
    'a': 0.34, 'an': 0.34, 'it': 0.31, 'that': 0.15,
    'my': 0.23, 'your': 0.23, 'our': 0.23, 'their': 0.23,
    'his': 0.20, 'her': 0.20, 'its': 0.20, 'them': 0.13,
}
UTILIZATION = {
    'utilize', 'utilizes', 'utilized', 'utilizing',
    'utilise', 'utilises', 'utilised', 'utilising',
}
APPLICATION = {'apply', 'applies', 'applied', 'applying'}
EMPLOYMENT = {'employ', 'employs', 'employed', 'employing'}
ADDITION = {'add', 'adds', 'added', 'adding', 'install', 'installing'}
INSTRUMENTAL = {'with', 'by', 'through'}
POSSESSION = {'have', 'has', 'had', 'having'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    # The verb itself carries a smaller signal, including common translations.
    if word in UTILIZATION | EMPLOYMENT:
        value = 0.21
    elif word in {'使用', '利用'}:
        value = 0.26
    elif word in {'use', 'uses'}:
        value = 0.065
    elif word in {'usage', 'utilization', 'utilisation'}:
        value = 0.10
    # Inflection endings completing a split 'utilize' or Russian 'use' stem.
    if not token.startswith(' ') and word.isalpha():
        if previous in {'util', 'utilis', 'utiliz'}:
            value = 0.50
        elif previous in {'использов', 'ользов'}:
            value = 0.43
    if previous == 'sử' and word == 'dụng':
        value = 0.68
    elif previous == '採' and word == '用':
        value = 0.42
    # A following word must actually start a new space-separated word.
    if token.startswith(' '):
        if previous in USE_FORMS:
            value += USE_FORMS[previous] * USE_COMPLEMENTS.get(word, 0.0)
            if previous == 'using' and word == 'this':
                value = 0.46
        elif previous in UTILIZATION | APPLICATION | EMPLOYMENT:
            scale = (0.68 if previous in UTILIZATION else
                     0.53 if previous in EMPLOYMENT else 0.38)
            value += scale * USE_COMPLEMENTS.get(word, 0.0)
        if word == 'the':
            if previous in INSTRUMENTAL | POSSESSION:
                value = 0.21
            elif previous == 'via':
                value = 0.40
            elif previous == 'from':
                value = 0.13
            elif previous == 'as':
                value = 0.09
            elif previous in {'that', 'which', 'all', 'but', 'be'}:
                value = -0.10
            elif previous in {'into', 'after', 'until', 'upon', 'out'}:
                value = -0.13
            elif previous in {'inside', 'outside', 'off'}:
                value = -0.19
            elif previous == 'to':
                value = -0.05
            elif previous == 'on':
                value = -0.03
            elif previous in ADDITION:
                value = 0.41
            elif previous in {'follow', 'following', 'follows'}:
                value = 0.27
        elif word == 'of' and previous in {'usage', 'utilization', 'utilisation'}:
            value = 0.54
    return (doc, word), value

programs.haiku:
"""layers.0.mlp.down_proj:194, the "use the" detector.

The component fires on the word right after a verb of using ("use", "using",
"used", "uses", "usage", "utilize", "employ", "leverage", and the Chinese
使用 / 利用). It is strongest on "the" ("using the", "use the"), then on "of"
("use of"), "this", "these", and other determiners such as "a", "its", "their".
It is weaker on "the" after words that name a means, instrument or
accompaniment ("with the", "by the", "via the", "through the", "from the",
"add the", "apply the"). It dips slightly on "the" after words of direction or
place ("into the", "after the", "across the", "until the"). The use-words
themselves ("utilize", "employ", "利用") also give a weak positive value.

Everything else is predicted as 0. The component has a diffuse background
(small positive and negative values on many content words) that this program
does not model, so it explains only the spiky part of the activation.
"""

# Verbs of using: the word right before the activation.
USE_VERBS = {
    "use", "uses", "using", "used", "usage", "utilize", "utilized", "utilizing",
    "employ", "employed", "leverage", "使用", "利用",
}

# Words that name a means, instrument or accompaniment: a weak push on "the".
MEANS_WORDS = {
    "with", "by", "via", "through", "from", "add", "adding", "apply", "applying", "install",
}

# Words of direction or place: a weak dip on "the".
PLACE_WORDS = {
    "into", "after", "across", "inside", "outside", "onto", "upon", "until",
    "throughout", "towards", "before", "below",
}

# Activation on the word right after a use-verb.
AFTER_USE = {
    "the": 1.3, "of": 0.9, "this": 0.5, "these": 0.4,
    "a": 0.27, "an": 0.27, "it": 0.25, "their": 0.2, "your": 0.2, "my": 0.2, "our": 0.2,
}

# The use-words themselves, which carry a weak activation.
USE_WORD_ITSELF = {"utilize", "utilized", "employ", "employed", "leverage", "使用", "利用"}

READS = ()


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    # Only look back one token, and only within the same document.
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2])
    if prev in USE_VERBS and cur in AFTER_USE:
        return None, AFTER_USE[cur]
    if cur == "the" and prev in MEANS_WORDS:
        return None, 0.2
    if cur == "the" and prev in PLACE_WORDS:
        return None, -0.12
    if cur in USE_WORD_ITSELF:
        return None, 0.25
    return None, 0.0

programs.sol:
"""Partial orthographic approximation of a word-continuation signal.

Training examples often gave positive responses to word pieces following
short stems, and negative responses to code-abbreviation boundaries. This
program approximates that contrast using named stems and identifier fields,
letter case, digits, and grammatical endings. Reference markup ref-type gets
a strong negative value. A few formatting conventions get small offsets.
Other contexts stay near zero; token-specific background is not modeled.
"""
import re

READS = ()
STEMS = set('''
abs adj app arg arr asm ast auth chr col com comp cond conf const conv coord
dec def dep desc dest dev dict dif diff dir dist div doc elem emp enc eng env
esc exec exp expr ext fmt gen hist inc inf inst int intr lib loc mag max mem
min mod norm obj org par param perf pl pref prim prob proc prof prog prom prop
ptr real rec ref reg rel rem rep res resid resp ret rev seq ser sig sim simp
src stab str struct tech temp tr var vec vers vis vol
'''.split())
FIELDS = set('''
all assign bank buffer chain conf count day decl entry errors event expr file
field fn freq function id idx impl integral items key len list macro mode name
names new no num offset on path pkg pointer replace resource rule scores status
str test token type utils value ver
'''.split())
INFLECTIONS = set('''
s es ed ing er ers ly est ness ment ments tion tions ation ations ition itions
ion ions ity ities able ible al ally ous ously ive ives ic ics ist ists ism isms
ize izing ized ify ified
'''.split())
BOUND = re.compile(
    r'^(?:re|de|dis|in|en|ex|pre|pro|con|com|per|sub)'
    r'[bcdfghjklmnpqrstvwxyz]{1,3}$'
)


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    s = t.strip()
    lower = s.lower()
    value = -0.001
    if t == '<|im_end|>':
        value = 0.042
    elif t == '</tool_response>':
        value = -0.083
    elif s == '!=':
        value = -0.08
    elif t == "'s":
        value = -0.02
    elif s == 'www':
        value = -0.21
    elif len(s) >= 2 and set(s) == {'·'}:
        value = 0.086
    elif len(s) >= 2 and set(s) == {'_'}:
        value = -0.038

    if (len(prefix.token_ids) < 2 or
            prefix.document_ids[-1] != prefix.document_ids[-2]):
        return None, float(value)
    prev = prefix.token_strings[-2].strip()
    stem = re.sub(r'^[^A-Za-z]*', '', prev).lower()
    if stem not in STEMS or not t:
        return None, float(value)
    bound = bool(BOUND.fullmatch(stem))
    if stem == 'ref' and t == '-type':
        value = -0.86
    elif t[0].isspace():
        value = -0.04
    elif s in ('s', 'S'):
        value = -0.38
    elif lower in FIELDS:
        value = -0.28
    elif s.isdigit():
        value = -0.22 if all(c in '0123' for c in s) else -0.085
    elif t.startswith('_'):
        field = s.lstrip('_').lower() in FIELDS
        value = (-0.44 if bound else -0.13) if field else -0.11
    elif t.startswith('.'):
        value = -0.08 if bound else -0.015
    elif s.isascii() and s.isalpha():
        if s.isupper():
            value = 0.02
        elif s[0].isupper():
            value = -0.18
        elif lower in INFLECTIONS:
            value = 0.03
        elif s[0] in 'aeiouy':
            value = 0.13 if bound else 0.06
        elif s[0] in 'rl':
            value = 0.10 if bound else 0.05
        else:
            value = -0.02
    elif t[0] in ':-=':
        value = -0.15
    else:
        value = -0.04 if bound else -0.015
    return None, float(value)

"""Approximate code references, especially member access and UI bindings.

Dotted names are positive, strongest for DOM lookup/events/content and Android
resources. File suffixes, namespaces and prose abbreviations are weaker. Nearby
syntax distinguishes declarations, HTML attributes and conditionals from prose.
Other triggers cover mentions, selectors, relative paths and HTTP/UI bindings.
Unmatched tokens return zero. Retain 256 characters, resetting per document.
Shared levels omit individual names' finer differences; a conservative 0.8 gain
was chosen from training-time model-output comparisons.
"""
import re

READS = ()
FILE_SUFFIXES = set('''com org net edu gov html htm json java js ts py cpp h
    hpp css xml txt png jpg jpeg gif pdf md csv svg go rs sh yaml yml jar
    zip gz exe dll uk de fr ru cn us nl php'''.split())
DOM_LOOKUP = {'getElementById', 'getElementsByClassName', 'getElementsByTagName'}
DOM_EVENTS = {'addEventListener', 'removeEventListener', 'preventDefault'}
DOM_CONTENT = {'querySelector', 'querySelectorAll', 'appendChild',
               'getAttribute', 'innerHTML', 'textContent'}
DOM_PROPERTIES = {'id', 'name', 'value', 'style', 'href', 'click'}
ANDROID_RESOURCES = {'id', 'layout', 'drawable', 'mipmap', 'string'}
HTTP_METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
ANNOTATIONS = {'FXML', 'Component', 'Service', 'RequestMapping',
               'GetMapping', 'PostMapping', 'PutMapping', 'DeleteMapping'}
DECLARATIONS = {'public', 'private', 'protected', 'static', 'export',
                'default', 'async', 'abstract', 'final'}
CONDITIONALS = {'if', 'elif', 'while', 'switch', 'catch'}
PRINTING = {'print', 'println', 'printf', 'sprintf', 'writeline'}
PACKAGES = {'util', 'lang', 'io', 'apache', 'springframework'}


def signal(s, before):
    word = s.strip()
    if len(s) > 1 and s[0] == '.' and (s[1].isalpha() or s[1] == '_'):
        name = s[1:]
        if name in FILE_SUFFIXES:
            return 0.0
        if ((name == 'g' and before.endswith('e')) or
            (name == 'e' and before.endswith('i')) or
            (name in {'S', 'K'} and before.endswith('U'))):
            return 0.07
        if before.endswith('R') and name in ANDROID_RESOURCES:
            return 2.1 if name == 'id' else 1.6
        if name in DOM_LOOKUP:
            return 2.3
        if name in DOM_EVENTS:
            return 1.8
        if name in DOM_CONTENT:
            return 1.4
        if name in DOM_PROPERTIES or name in HTTP_METHODS:
            return 1.0
        if name.lower() in PRINTING or name in PACKAGES:
            return 0.12
        if name in {'git', 'github'} or name.startswith('_'):
            return 0.30
        if name == 'append':
            return 0.20
        if name[0].isupper():
            return 0.34 if len(name) <= 2 else 0.48
        return 0.58 if len(name) == 1 else 0.67
    if word == '@':
        return 0.30
    if (word.lstrip('@') in ANNOTATIONS and
        (word.startswith('@') or before.rstrip().endswith('@'))):
        return 1.0
    if word in HTTP_METHODS:
        return 0.70
    if word in {'textContent', 'innerHTML'} and before.endswith('.'):
        return 1.0
    declaration = word in {'class', 'function'} or s == '(function'
    conditional = s.startswith(' (') or s in {'(', '(!'}
    if declaration or conditional:
        previous = re.search(r'([A-Za-z]+)\s*$', before)
        previous = previous.group(1) if previous else ''
        if declaration:
            if s == word and before[-1:].isalnum():
                return 0.0
            if s == '(function':
                return 0.90
            if previous in DECLARATIONS:
                return 1.20 if word == 'class' else 0.85
            if word == 'class' and re.search(r'<[^>]*$', before):
                return 1.15
            line_start = re.fullmatch(r'\s*\d*\s*', before.rsplit('\n', 1)[-1])
            if line_start or re.search(r'[=:,(]\s*$', before):
                return 0.45 if word == 'class' else 0.85
            return 0.03 if word == 'class' else 0.13
        if previous in CONDITIONALS:
            return 0.55
    if word == 'public':
        line_start = re.fullmatch(r'\s*\d*\s*', before.rsplit('\n', 1)[-1])
        return 0.45 if line_start else 0.10
    if word in {'void', 'constructor'}:
        return 0.30
    if s == 'import':
        return 0.78 if ';' in before else 0.12
    if re.search(r"['\"]\.$|['\"]\./$", s):
        return 0.80
    if re.search(r"['\"]#$", s) or ('$' in s and '#' in s):
        return 0.70
    if word in {'div', '<div'}:
        if word == '<div' or before.rstrip().endswith(('<', '</')):
            return 0.85
    if word in {'onclick', 'onClick', 'onSubmit', 'className'}:
        return 1.10 if word != 'className' else 0.80
    if word in {'id', 'href'} and re.search(r'<[^>]*$', before):
        return 0.70
    if word == 'click' and 'addEventListener' in before[-100:]:
        return 1.50
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (before + s)[-256:]), float(0.8 * signal(s, before))

programs.haiku:
"""Property and method names after a dot in source code.

layers.0.mlp.down_proj:196 fires on the token that names a member after a dot in code,
such as `.getElementById`, `.addEventListener`, `.value`, `.log` or `.status`. The
strongest responses are to web and DOM style APIs. It fires more weakly on the keywords
that open a declaration (`import`, `function`, `class`, `public`), on `(` right after
`if` or `while`, and on `@` annotations. Dots that begin file names, domains or
abbreviations (`.py`, `.png`, `.org`) do not fire, and neither does anything else.
"""

import re

READS = ()

# A dot followed by an identifier, as one token: ".value", ".getElementById".
MEMBER = re.compile(r"\.[A-Za-z_]\w*")

# Names that follow a dot in file names, domains and packages rather than in code.
NOT_A_MEMBER = {
    "py", "java", "js", "ts", "html", "htm", "png", "jpg", "gif", "json", "yml", "jar",
    "org", "edu", "gov", "com", "net", "pdf", "txt", "md", "h", "hpp", "cpp", "css",
    "apache", "google", "springframework", "junit", "wikipedia", "amazon",
}

DECLARATION_WORDS = {"import", "function", "class", "public"}
CONTROL_WORDS = {"if", "while"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    word = token.strip()
    if MEMBER.fullmatch(token):
        return carry, (0.0 if token[1:] in NOT_A_MEMBER else 0.5)
    if word in DECLARATION_WORDS:
        return carry, 0.35
    if word == "(" and previous in CONTROL_WORDS:
        return carry, 0.45
    if word == "@":
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""Respond to short presentational, invitational and relational phrases.

The main negative triggers are Here is/Here's, Let me/Let's, and a temporal
connector followed by a pronoun. Purpose words and descriptive relations
provide positive responses. This is a lexical approximation: only the current
and previous token matter, with case retained for sentence-opening phrases.
At a document start there is no previous word; a few spatial and temporal
words receive their separate, standalone response instead. Constants are
approximate training values; unmatched tokens receive a near-zero background.
"""
READS = ()

# Pronouns interact particularly strongly with temporal connectors.
PRONOUN_WEIGHT = {
    'i': 2.12, 'you': 3.04, 'we': 2.64, 'they': 1.66,
    'he': 1.09, 'she': 1.37, 'it': 1.54, 'me': 1.34, 'us': 1.63,
}
INITIAL_MARKERS = {
    'here': -1.20, 'before': -1.53, 'below': -2.00, 'above': -0.90,
    'prior': -1.14, 'already': -0.75, 'within': -0.52,
    'first': -0.36, 'next': -0.55, 'now': -0.43,
    'let': -0.33, 'after': -0.28, 'need': -0.75, 'needs': -0.61,
