TEMPORAL = {'before': 1.0, 'after': 0.57, 'once': 0.40,
            'until': 0.22, 'now': 0.24}

# Standard preposition phrases; signs distinguish this component's responses,
# not whether a phrase is grammatical or desirable.
RELATIONS = {
    'by': {
        'followed': -2.76, 'preceded': -2.16, 'step': -1.87,
        'accompanied': -1.59, 'supported': -1.37, 'start': -1.22,
        'surrounded': -0.97, 'separated': -0.79, 'side': -0.80,
        'given': 0.85, 'defined': 0.79, 'described': 0.60,
        'characterized': 0.46, 'indexed': 0.64,
    },
    'to': {
        'prior': -1.71, 'closer': -1.16, 'close': -0.96,
        'near': -1.23, 'next': -0.98, 'adjacent': -0.85,
        'ready': -0.82, 'follow': -1.00, 'proximity': -1.15,
        'according': 0.31, 'corresponds': 0.72,
        'corresponding': 0.59, 'correspond': 0.45,
        'related': 0.27, 'seem': 0.41, 'seems': 0.29,
    },
    'with': {'associated': 1.03, 'accordance': 0.31},
    'on': {'work': -0.54, 'working': -0.62,
