"""An opening-delimiter response, sensitive to the text immediately to its left.

Parentheses attached to numbers or short names are strongest. Programming-style
names, spaces before the opener, quotes, and line boundaries weaken the response.
Square brackets have a broader positive response. A fused argument changes the
strength: single-letter variables preserve it; long words and quotes suppress it.
Other tokens are zero except for a small negative response to open curly braces.
This captures the prominent delimiter signal, not the component's diffuse lexical
variation on ordinary words.
"""
import re

READS = ()
PROGRAMMING_WORDS = set(
    'print printf println len str int float char varchar bool boolean string '
    'double long short void range type list dict set tuple repr isinstance '
    'assert if while for switch catch'.split()
)


def left_strength(p):
    """Return strengths for an attached and a space-separated parenthesis."""
    if not p:
        return 0.0, 0.0
    q = p.strip()
    if '\n' in p or '\r' in p:
        return -0.20, -0.05
    if not q:
        return -0.08, -0.07
    if q[-1].isdigit():
        return 1.01, -0.01
    word_match = re.search(r'\w+$', p)
    if not word_match:
        if q[-1] in '\"\'`“”':
            return 0.07, -0.15
        if q[-1] in ')]}':
            return 0.30, 0.06
        return 0.27, -0.08
    word = word_match.group()
    if word.lower() in PROGRAMMING_WORDS:
        return 0.16, 0.03
    if '.' in p or '_' in p:
        return 0.32, 0.02
    if len(word) <= 2:
        return 0.91, 0.13
    if not word.islower() and not word.isupper():
        return 0.48, 0.14
    return (0.65 if p.startswith((' ', '\t')) else 0.56), 0.10


def estimate(s, p):
    index = max(s.rfind('('), s.rfind('['), s.rfind('（'), s.rfind('［'))
    if index < 0:
        return -0.07 if '{' in s and '}' not in s else 0.0
    opener, tail, lead = s[index], s[index + 1:], s[:index]
    square = opener in '[［'
    if opener in '（［':
        return 0.10
    if ')' in tail or ']' in tail:
        return -0.03
    if lead.strip():
        if not square and lead.endswith(']'):
            return 0.02  # Markdown's ]( link delimiter is not a strong opener.
        if lead[-1:] in (']', '}', ')'):
            return 0.40
        if lead == '\\':
            return 0.19 if square else -0.09
        return 0.22 if square else 0.07
    attached, spaced = left_strength(p)
    if lead:
        return 0.24 + 0.19 * spaced if square else spaced
    variable = tail.isascii() and tail.isalpha() and len(tail) == 1
    if square:
        if not tail:
            return 0.18 + 0.54 * attached
        if variable:
            return 0.31 + 0.24 * attached
        if tail == '\\':
            return 0.30 + 0.40 * attached
        return 0.17 + 0.10 * attached
    if not tail:
        return attached
    if variable:
        return 0.68 * attached
    if tail.isalpha():
        return -0.08 + 0.21 * attached
    if tail.startswith(('\n', '\r')):
        return 0.21 + 0.12 * attached
    if tail == '\\':
        return 0.12 + 0.60 * attached
    if tail.startswith('\\'):
        return 0.03 + 0.13 * attached
    if tail == '-':
        return 0.18 + 0.22 * attached
    if tail[:1] in '\"\'`':
        return -0.04 + 0.13 * attached
    return 0.03 + 0.11 * attached


def step(carry, prefix, upstream):
    p = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            p = prefix.token_strings[-2]
    return None, float(estimate(prefix.token_strings[-1], p))

programs.haiku:
"""Layer-0 MLP down-projection, component 200: an "opening bracket glued to the word
before it" detector.

It fires on "(" or "[" that attaches directly to the token before it, as in a
parenthetical or a call-like label: "steel mill(steel)", "GF(7)", "f(x)", "Sheet1[Date]",
"[17]" after a word. It is strongest for a bare bracket and for a label that looks like
maths (a single letter, a capital, or a name with a digit). It is weak when the label looks
like code (camelCase, a dot or underscore, as in `charAt(` or `substring(`), and it is
dampened when code-like punctuation (; { } = < > _) occurs in the last 12 tokens. A
bracket with a space before it gets a small value, and "( " or "[ " after a space is
weaker still. Everything else predicts 0.
"""

READS = ()

CODE_CHARS = set(";{}=<>_")


def _ends_wordy(s):
    return bool(s) and (s[-1].isalnum() or s[-1] in ')]}"\'')


def _math_label(s):
    s = s.strip()
    return len(s) == 1 or s.isupper() or any(c.isdigit() for c in s)


def _code_label(s):
    s = s.strip()
    return "." in s or "_" in s or any(a.islower() and b.isupper() for a, b in zip(s, s[1:]))


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    body = tok.lstrip(" ")
    first = next((i for i, c in enumerate(body) if c in "(["), None)
    if first is None or not _ends_wordy(prev):
        return None, 0.0
    bracket = body[first]
    after = body[first + 1 : first + 2]
    if after in ('"', "'", ")", "]"):
        return None, 0.0
    if first > 0:
        value = 0.2
    elif tok.startswith(" "):
        value = 0.3 if bracket == "[" else 0.08
    elif after:
        value = 0.2 if bracket == "(" else 0.4
    else:
        value = 0.6
    if first == 0 and not tok.startswith(" "):
        if _code_label(prev):
            value *= 0.4
        elif _math_label(prev):
            value *= 1.5
    code = sum(c in CODE_CHARS for t in toks[-13:-1] for c in t)
    return None, value * 0.9 ** min(code, 6)

programs.luna:
"""Approximate the component's cue for possible states versus reported evidence."""

READS = ()

STATE_WORDS = {
    "be", "exist", "happen", "occur", "consist", "contain", "hold", "seem",
}
EVIDENCE_WORDS = {
    "see", "seen", "find", "found", "hear", "heard", "detect", "detected",
    "understand", "tell", "identify", "infer", "determine", "predict",
}
MODALS = {"can", "could", "may", "might", "must", "cannot"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    previous = prefix.token_strings[-2].strip().lower() if same_doc else ""

    # Verbs of being/occurrence/possession are often positive, especially after a modal.
    if word == "be":
        return None, {"can": 3.4, "could": 2.5, "cannot": 2.7,
                      "may": 0.9, "might": 0.7}.get(previous, 0.8)
    if word == "have":
        return None, {"can": 4.4, "could": 3.4,
                      "may": 0.8, "might": 0.8}.get(previous, 0.2)
    if word in STATE_WORDS:
        return None, 1.0 if previous in MODALS else 0.65
    if word == "also":
        return None, 2.0 if previous == "can" else 0.2

    # Seeing, finding, and reporting evidence tend the other way.
    if word == "see":
        return None, -5.3 if previous in MODALS else -0.9
    if word == "seen":
        return None, -3.7 if previous == "be" else -0.7
    if word == "found":
        return None, -2.8 if previous == "be" else -0.6
    if word in EVIDENCE_WORDS:
        return None, -2.0 if previous in MODALS else -0.65
    if word == "easily" and previous in MODALS:
        return None, -2.0
    return None, 0.0

programs.sol:
"""Approximate a mixed spacing and Italian-function-word response.

Tabs and single non-breaking spaces usually give positive signals. Runs,
newlines and the first position of a document modify the spacing response.
A decaying tally of Italian versus other-language function words gates an
Italian vocabulary: articles and fused prepositions are mostly positive,
while 'per' and 'non' are strongly negative. Token fragments receive weaker
signals. These patterns stood out in training examples. The tally resets
at document boundaries; other text predicts zero.
"""
READS = ()

ITALIAN_CUES = set('''
di che il gli della delle dello degli dei nella nello nelle nel noi
sono siamo questo questa questi queste anche così quindi perché nostro
nostra nostri vostre vostro avete aveva hanno essere dalla dal dalle
ai alla alle uno è più
'''.split())
OTHER_CUES = set('''
the of and to is that for with this are was on be from your you not they
it have has but an as at can will les des dans pour une est los las el
por para en der die das und von mit ist zu ein
'''.split())

WEAK_ITALIAN_CUES = set('e le la con del non per un una lo ma si come'.split())

# Familiar Italian grammatical classes, with fitted response magnitudes.
ARTICLES = {
    'il': 0.50, 'lo': 1.35, 'la': 0.65, 'i': 1.00, 'gli': 0.65,
    'le': 1.00, 'un': 1.05, 'uno': 1.80, 'una': 0.70,
}
PREPOSITIONS = {
    'di': -0.14, 'in': 0.20, 'con': 0.45, 'per': -1.85, 'fra': 1.15,
    'al': 1.25, 'ai': 1.15, 'allo': 1.60, 'alla': 0.60, 'alle': 1.35,
    'del': 1.00, 'dello': 1.60, 'della': 0.38, 'delle': 0.65,
    'dei': 0.65, 'degli': 0.75, 'dell': 0.60,
    'nel': 0.45, 'nella': 0.47, 'nelle': 0.55, 'nei': 0.75,
    'dal': 0.25, 'dalla': 0.25, 'sul': 0.55,
}
PARTICLES = {
    'non': -1.65, 'mai': -0.60, 'che': -0.40, 'ma': -0.45,
    'e': 0.70, 'ed': 0.90, 'o': 0.55, 'è': -0.20, 'sono': -0.20,
}


def spacing(text, previous):
    if text == '\u00a0':
        if previous.endswith('\u00a0'):
            return 0.36 if previous == '\u00a0' else 0.18
        if not previous:
            return 0.68
        if previous and not previous.strip(' '):
            return 0.27
        return 0.93
    if text and not text.strip('\t'):
        if not previous:
            return -0.06 if len(text) == 1 else 0.25
        if previous.endswith('\t'):
            return 0.03 if previous == '\t' else -0.07
        if len(text) == 1:
            if previous and not previous.strip(' '):
                return 0.56
            return 0.89 if previous.strip().isdigit() else 0.95
        if len(text) == 2:
            return 0.69
        return 0.63 if len(text) <= 5 else 0.55
    if text.startswith('\t') and not text.strip('\t\r\n'):
        if not previous:
            return 0.19
        return 0.43 if previous.strip().isdigit() and text.count('\t') == 1 else 0.27
    if '\u00a0' in text and text.isspace():
        if text == ' \u00a0':
            return -0.05 if previous.endswith('\u00a0') else 0.44
        return -0.25 if previous.endswith('\u00a0') else 0.10
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, italian, other = '', 0.0, 0.0
    else:
        _, previous, italian, other = carry
    word = text.strip().lower()
    # Count word beginnings, not accidental syllables inside longer words.
    beginning = text.startswith(' ')
    clue = 0.0
    if word in ITALIAN_CUES:
        clue = 1.0
    elif word in WEAK_ITALIAN_CUES:
        clue = 0.25
    italian = 0.99 * italian + (clue if beginning else 0.0)
    other = 0.99 * other + (beginning and word in OTHER_CUES)
    confidence = min(1.0, max(0.0, (italian - other - 0.5) / 1.5))
    value = spacing(text, previous)
    if value is None:
        value = ARTICLES.get(word, PREPOSITIONS.get(word, PARTICLES.get(word, 0.0)))
        value *= confidence
        if not text.startswith(' '):
            value *= 0.35
        if word in ('per', 'non') and text.strip()[:1].isupper():
            value *= 0.65
    return (doc, text, italian, other), float(value)

"""A negative response to the ght spelling family, with weaker related clusters.

Common English -ight/-ought roots are assigned six approximate strength
bands. Bare fragments such as 'ight' are strongest. Compounds and following
syllables usually weaken the response. Smaller values cover ngth, cht, lth,
and dth, directions, think/rough families, and some night/light translations.
This is a token-local approximation; unrelated and contextual effects are
left at zero rather than memorized in a token table.
"""
READS = ()

GHT_BANDS = (
    (-3.2, ('flight', 'sight', 'fight', 'knight', 'drought', 'fought')),
    (-2.3, ('night', 'thought', 'height', 'tight', 'light', 'wright', 'fright')),
    (-1.8, ('naughty', 'bright', 'straight')),
    (-1.35, ('right', 'eight', 'weight', 'sought')),
    (-0.95, ('brought', 'bought', 'taught', 'might')),
    (-2.15, ('ought',)),
)
ROOTS = tuple((root, value) for value, roots in GHT_BANDS for root in roots)


def response(token):
    word = token.strip().lstrip('._-([\\').lower()
    if 'ght' in word:
        if not token[:1].isspace() and word.startswith(('ight', 'ought', 'ught')):
            value = -3.7
        else:
            value = next((v for root, v in ROOTS if word.startswith(root)), None)
            if value is None:
                value = next((0.3 * v for root, v in ROOTS if root in word), -0.2)
        if not word.endswith(('ght', 'ghts')) and word != 'naughty':
            value *= 0.65 if word.endswith('ghting') else 0.4
