    if 'ngth' in word:
        value = -1.4 if word.startswith('length') else -0.7
        return value if word.endswith(('ngth', 'ngths')) else value * 0.4
    if word.endswith('cht'):
        return -0.3 if word == 'nicht' else -1.2
    if word.endswith('lth'):
        return -0.95 if word in ('health', 'wealth') else -0.1
    if word.endswith('dth'):
        return -0.8
    if word.endswith(('north', 'south', 'northeast', 'southeast')):
        return -0.9
    if word in ('east', 'west', 'month', 'months'):
        return -0.45
    if 'think' in word and word.isalpha():
        return -0.5
    if word in ('rough', 'tough', 'dough', 'cough', 'ough'):
        return -0.85
    if word.startswith('weigh') or word in ('neigh', 'leigh'):
        return -1.2
    if word in ('igh', 'ugh', 'gh', 'ht', 'hte', 'orth', 'outh'):
        return -1.65 if word in ('igh', 'ugh') else -0.6
    # Night-related words: Chinese, Russian, Spanish, and French.
    if word in ('夜', '一夜', '晚上', 'ночь', 'ноч', 'noche', 'nuit'):
        return -1.1
    # Light: Chinese, French, and Russian.
    if word in ('光', 'lumière', 'свет'):
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

