    'consequence': 0.4, 'consequences': 0.6, 'suffix': 1.2,
    'dopo': 0.36, 'послед': 0.53, '之后': 0.42,
    'poster': 2.2, 'posters': 2.0, 'postal': 1.9, 'postage': 0.95,
    'posterior': 1.45, 'posture': 1.35, 'postcode': 1.6,
    'compost': 1.1, 'outpost': 1.2, 'blogging': 1.0,
    '帖': 4.2, '帖子': 4.0, '贴': 3.1, '貼': 2.1, '邮': 1.9, '글': 1.75,
