    elif word == 'Message':
        value = 0.6
    elif word == 'Suffix':
        value = 1.6
    elif first and word == 'After':
        value = 1.27

    # Posting metadata, and fragments immediately completing a post-word.
    prev = previous.lower()
    if token == ':' and prev in {'posts', 'posted'}:
        value = 0.48
