READS = ()

_AFTER = ("after", "following", "subsequent", "послед")
_POST_THREADS = frozenset(("帖",))
_AFTER_CHARS = frozenset(("后", "後"))
_ONLINE_WRITING = frozenset((
    "blog", "blogs", "forum", "forums", "message", "messages",
    "permalink", "article", "articles", "thread", "threads",
))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    word = token.strip(".,;:!?()[]{}\"'")

    if word == "post":
        return None, 7.2
    if word == "posts":
        return None, 4.6
    if word.startswith("post"):
        return None, 3.0
    if any(word.startswith(root) for root in _AFTER):
        return None, 0.8
    if word in ("suffix", "-suffix", "_suffix"):
        return None, 0.9
    if word in _ONLINE_WRITING:
        return None, 0.8
    if any(char in word for char in _POST_THREADS):
        return None, 4.0
    if any(char in word for char in _AFTER_CHARS):
        return None, 0.7
    if word in ("aftermath", "consequence", "consequences"):
        return None, 0.8
    return None, 0.0

programs.sol:
"""Approximate the strong negative response to short Arabic alif fragments.

Consonant, fragment length, leading space, and vowel marks set the strength.
Indic long-aa signs and a few other a-like letters have smaller responses;
Korean -da endings are another small response family. All other text is zero.
Constants are rounded training averages. This omits weak lexical responses
and does not claim the component is a universal phonetic detector.
