import unicodedata as ud

READS = ()

# Strength of an alif-ending syllable, calibrated by its consonant.
ALIF_AFTER = {
    'ل': 3.8, 'ر': 3.8,                 # la, ra
    'ب': 3.25, 'ن': 3.25, 'م': 3.5,    # ba, na, ma
    'و': 2.75, 'د': 2.75,              # wa, da
    'ه': 2.2, 'ذ': 1.9,                # ha, dha
    'ي': 3.0, 'ی': 3.0, 'ش': 0.9,      # ya, sha
}
OTHER_A_LETTERS = {'ā': -0.6, 'א': -0.5, 'ά': -0.37, 'а': -0.11}


def aa_sign_name(text):
    for c in text:
        name = ud.name(c, '')
        if 'VOWEL SIGN AA' in name:
            return name
    return ''


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s, space = token.strip(), token != token.lstrip()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = 0.0
    aa = aa_sign_name(s)
    if s and all('\u0600' <= c <= '\u06ff' for c in s):
        letters = ''.join(c for c in s if ud.category(c).startswith('L'))
        n = len(letters)
        if letters.endswith('ا'):
            if n == 1:
                value = -1.01 if space else -4.4
                if not space and previous.endswith('ی'):
                    value = -3.2  # Persian yeh followed by alif: ya.
                elif not space and previous.endswith('ه'):
                    value = -3.9
            else:
                consonant = letters[-2]
                value = -ALIF_AFTER.get(consonant, 2.5) * 0.65 ** (n - 2)
                if space:
                    value *= 0.5 if consonant in 'ويی' else 0.68
            if 'ً' in s:
                value *= 0.5  # Fathatan: the tanwin (an) mark.
            elif 'َ' in s:
                value *= 0.82  # Fatha: short-a mark.
        elif letters == 'آ':
            value = -1.43 if space else -2.7
        elif letters == 'أ':
            value = -0.30 if space else -0.6
        elif letters == 'إ':
            value = -0.74
        elif letters.startswith('ا') and n == 2:
            value = -1.4 if letters[-1] in 'یئ' else -0.25
            if letters[-1] == 'ل':
                value = 0.05  # Definite article al-.
        elif n == 1:
            value = -0.15 if letters in 'یي' else 0.1
            if letters == 'و':
                value = -0.04 if space else -0.27
        if letters in ('هذا', 'هنا', 'أنا'):  # Whole words: this, here, I.
            value = -0.2
        if not letters and any(ud.category(c) == 'Mn' for c in s):
            value = -0.58 if s == 'ً' else -0.4
    elif aa:
        value = -1.0
        if 'DEVANAGARI' in aa or 'GURMUKHI' in aa:
            value = -1.85 if '�' in s else -2.37
    elif s in OTHER_A_LETTERS:
        value = OTHER_A_LETTERS[s]
    elif 'ā' in s:
        value = -0.1
    elif s.endswith('า') and len(s) <= 3:
        value = -1.02 if '้' in s else -0.5
    elif s.endswith('다'):
        if s.endswith('니다'):  # Polite -nida differs from plain -da.
            value = 0.2
        elif s == '다':
            value = -0.85 if space else -0.52
        else:
            value = -0.65 if space or '�' in s else -0.43
    elif s == '아':
        value = -0.96 if space else -0.58
    elif s == '해':
        value = -0.3 if space else -0.7
    elif s in ('ไ', 'อ'):
        value = -0.85 if s == 'ไ' else -0.38
    if s == '�' and previous:
        # A token's bytes may finish an Indic sign begun in the last token.
        aa = aa_sign_name(prefix.text_prefixes[-1][-1:])
        if aa:
            value = -2.4 if 'GURMUKHI' in aa else -1.0
    return (doc, token), float(value)

programs.haiku:
"""Arabic-script long-a syllables: short Arabic-script pieces that end in alef (ا).

Component layers.0.mlp.down_proj:207 is almost silent on English and code. Its large
negative activations come from Arabic-script (Arabic, Persian, Urdu) token pieces that end
in the letter alef, ا, the spelling of a long "a" vowel: ا, لا, ما, ها, يا, نا, وا, را, با.
The strongest cases are short pieces cut out of the middle of a word (no leading space):
a lone ا is about -4.3, a two-letter piece such as ما about -2.8, a three-letter piece about
-1.8. A piece that starts a word (leading space) is weaker: about -1 for a lone ا, and about
-2.3 for two letters. Alef-madda, hamza-alef and Persian yeh endings are weaker still, and
everything else (English, digits, code, other scripts, longer Arabic words) predicts 0.

The prediction reads only the current token and whether it begins with a space, so it
needs no memory across positions.
"""

READS = ()

# Activation for a joined (no leading space) alef-final piece, by its number of letters.
JOINED = {1: -4.3, 2: -2.8, 3: -1.8}
# For a piece that begins a word (leading space), by number of letters.
SPACED = {1: -1.0, 2: -2.3}


def _arabic_piece(text):
    """True if the token is made only of Arabic-script characters (letters or marks)."""
    import unicodedata

    body = text.strip()
    return bool(body) and all("ARABIC" in unicodedata.name(ch, "") for ch in body)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = 0.0
    if _arabic_piece(text):
        body = text.strip()
        last = body[-1]
        n = len(body)
        joined = not text.startswith(" ")
        if last == "ا":
            if joined:
                value = JOINED.get(n, -1.1)
            else:
                value = SPACED.get(n, -0.8)
        elif last in "آإأ":
            value = -0.5
        elif last in "ئیو" and joined:
            value = -0.5
    return carry, float(value)

