READS = ()

COMMON_UNITS = {
    "inch", "inches", "foot", "feet", "mile", "miles", "yard", "yards",
    "cup", "cups", "teaspoon", "teaspoons", "tablespoon", "tablespoons",
    "pound", "pounds", "ounce", "ounces", "尺",
}

OTHER_UNITS = {
    "m", "cm", "mm", "km", "meter", "meters", "metre", "metres",
    "g", "kg", "mg", "gram", "grams", "kilogram", "kilograms", "lb",
    "lbs", "oz", "ml", "l", "liter", "liters", "litre", "litres",
    "s", "sec", "second", "seconds", "min", "minute", "minutes",
    "hour", "hours", "day", "days", "year", "years", "hz", "khz",
    "mhz", "ghz", "gb", "mph", "kph", "radian", "radians", "degree",
    "degrees", "volt", "volts", "kv", "watt", "watts", "joule", "joules",
    "erg", "ev", "pa", "kpa", "mpa", "bar", "psi",
}

NUMBER_WORDS = {
    "zero", "one", "two", "three", "four", "five", "six", "seven",
    "eight", "nine", "ten", "eleven", "twelve", "half", "quarter",
    "dozen", "hundred", "thousand", "million", "billion",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(".,;:()[]{}\"'`_")
    if word in COMMON_UNITS | OTHER_UNITS | {"/s", "/l"}:
        same_doc = prefix.document_ids[-1]
        previous = []
        for i in range(len(prefix.token_strings) - 1, max(-1, len(prefix.token_strings) - 4), -1):
            if prefix.document_ids[i] != same_doc:
                break
            previous.append(prefix.token_strings[i].strip().lower())
        has_number = any(any(ch.isdigit() for ch in token) for token in previous)
        has_number |= any(token.strip(".,/-") in NUMBER_WORDS for token in previous)
        # Rates like 1000 km/s put the number just before the named unit.
        has_number |= len(previous) >= 2 and previous[0] in {"km", "m", "mi"} and any(
            ch.isdigit() for ch in previous[1]
