        if has_number:
            return None, -2.5 if word in COMMON_UNITS else -0.9
    if word == "尺" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            if prefix.token_strings[-2].strip() == "公":
                return None, -2.5
    if word == "per" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            if "potential" in prefix.token_strings[-2].lower():
                return None, -0.8
    if word == "unit" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            if prefix.token_strings[-2].strip().lower() == "per":
                return None, -1.0
    if word == "mass" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            if prefix.token_strings[-2].strip().lower() == "unit":
                return None, -0.8
    return None, 0.0

programs.sol:
"""A local spelling-boundary approximation, learned from training averages.

Mostly negative after Latin c/C, with size adjusted by fragment lengths,
initial-letter classes, case, and c/k/q counts. C++/C#/csharp are positive
exceptions. Lowercase continuations after Cyrillic с/С are positive; the
editing-operation suffix _replace is negative. Isolated c/C/С at a document
start is mildly positive. Otherwise predict zero, not a lexical lookup.
Carry the preceding non-NUL token across UTF-16-like NUL separators, resetting
at document changes. Token-specific magnitudes remain unexplained.
"""
READS = ()
VOWELS = 'aeiouáàâäéèêëíìîïóòôöúùûü'
# Stops, nasals, liquids, labial fricatives, sibilants, and c/h/k/q spellings.
LETTER_GROUPS = (
    ('bdgpt', -0.216),
    ('mn', -0.298),
    ('lr', -0.329),
    ('fv', -0.081),
    ('sz', -0.175),
    ('chqk', 0.074),
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    carry = (document, previous if token == '\x00' else token)
    value = 0.0
    if token == '_replace':
        return carry, -0.480
    if not token or token == '\x00':
        return carry, value
    if not previous and token.strip() in ('c', 'C', 'С'):
        return carry, 0.23
    first = token[0]
    lower = token.lower()
    if previous.endswith(('c', 'C')):
        length = len(previous.strip())
        if first.isalpha():
            value -= 0.315
            value += 0.051 * (min(length, 6) - 2)
            value += 0.050 * (min(len(token), 8) - 3)
            if length == 1:
                value += 0.239
            if lower[0] in VOWELS:
                value += 0.050 + (0.012 if length == 1 else 0.0)
            for letters, adjustment in LETTER_GROUPS:
                if lower[0] in letters:
                    value += adjustment
            value -= 0.051 if first.isupper() else 0.0
            value += 0.214 * sum(c in 'ckq' for c in lower)
        elif first.isdigit():
            value -= 0.287
            if previous.lower().endswith('xc'):
                value -= 0.372  # Escaped hexadecimal byte prefix.
        elif first.isspace():
            value -= 0.011
        else:
            value -= 0.029
            if first == '(':
                value -= 0.132
            if first == '.' and len(token) > 1 and token[1].isalpha():
                value -= 0.119
            if length == 1 and token.startswith('++'):
                value += 0.800
            if length == 1 and first == '#':
                value += 0.961
        if token == 'sharp':
            value = 0.74
    elif previous.endswith(('с', 'С')):
        if first.islower():
            value += 0.118
            if previous.endswith('С'):
                value += 0.309
        elif first.isspace():
            value += 0.073
    return carry, float(value)

programs.haiku:
"""Latin 'c' carry-over: the component dips negative on the token right after a
fragment that ends in the letter c (EC|2, IC|RP, xc|, \\xc|2, ac|etate, C|ron), and is
near zero elsewhere. Common -ic words (public, electric) and standalone letters do not count."""

READS = ()

LEADS = (" ", "\t", "\n")


def ends_in_latin_c(s):
    s = s.strip()
    return s[-1:] in ("c", "C") and s.isalpha()


def common_ic_word(s):
    s = s.strip()
    return len(s) >= 5 and s.isalpha() and s.lower().endswith("ic")


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev, cur = prefix.token_strings[-2], prefix.token_strings[-1]
    if prev.strip()[-1:] in ("с", "С"):  # Cyrillic lookalike of c
        return None, 0.12
    if not ends_in_latin_c(prev) or common_ic_word(prev):
        if cur == "_replace" and prev == "str":
            return None, -0.45
        return None, 0.0
    if cur.startswith(LEADS):
        return None, -0.03
    if cur.strip().isdigit() or cur.strip().isupper():
        return None, -0.34
    return None, -0.10

programs.sol:
"""Detect second-person address, especially English 'You' starting a clause.

Lowercase 'you' is weaker in questions, conditions, and object position.
Possessives and non-English second-person forms respond more modestly.
Copulas and perfect auxiliaries immediately following 'you' retain part of
its response. Capitalized forms are stronger near the start of a document.
"""
READS = ()

COORDINATORS = {'and', 'but', 'or', 'so', 'because'}
CONDITIONALS = {'if', 'when', 'whenever', 'unless', 'where', 'once', 'whether'}
MODALS = {'could', 'would', 'should', 'may', 'might', 'must', 'shall'}
OBJECT_VERBS = {'help', 'helps', 'assist', 'tell', 'tells', 'let', 'remind',
                'give', 'see', 'show', 'invite', 'hope', 'wish', 'want'}
SECOND_PERSON = {
    '你': 0.85, '您': 1.15, 'вы': 0.8, 'Вы': 0.95,
    'вам': 0.85, 'Вам': 1.0, 'вас': 0.65, 'вашего': 0.6,
    'vous': 0.9, 'Vous': 1.7, 'você': 0.7, 'Você': 1.8,
    'Anda': 0.8, 'あなた': 1.4, 'bạn': 1.2, 'Ihrem': 0.4,
}
OTHER_PRONOUNS = {
    'I': 0.12, 'We': 0.13, 'They': 0.21, 'its': 0.125,
    'we': -0.09, 'they': -0.09, 'he': -0.05, 'she': -0.11,
    'it': -0.07, 'my': -0.065, 'our': -0.09, 'their': -0.05,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, previous_value, n, tail = '', 0.0, 0, ''
    else:
        _, previous, previous_value, n, tail = carry
        n += 1
    raw = prefix.token_strings[-1]
    word = raw.strip()
    prev = previous.strip()
    p = prev.lower()
    tail = (tail + raw)[-12:]
    comma = prev.endswith((',', ':', ';'))
    clause = comma or p in COORDINATORS
    value = OTHER_PRONOUNS.get(word, 0.0)

    if word == 'You':
        # A shallow document-start enhancement, not a long-lived state.
        value = 4.05 + 1.3 / (1.0 + n / 24.0)
        if prev.isalpha():
            value -= 0.6
        if first:
            value = 8.89 if raw.startswith(' ') else 11.0
    elif word == 'you':
        value = 1.5
        if first:
            value = 3.93
        elif not raw.startswith(' '):
            value = 2.9
        elif comma:
            value = 2.83
        elif p in COORDINATORS:
            value = 2.45
        elif p == 'can':
            value = -0.25 if prev.istitle() else 0.08
        elif p in MODALS or p in {'do', 'did', 'does', 'how'}:
            value = 0.6
        elif p in CONDITIONALS:
            value = 1.2 if prev.istitle() else 0.9
        elif p in OBJECT_VERBS:
            value = 0.7
        elif p == 'thank':
            value = 1.7
        elif p == 'to':
            value = 1.0
    elif word in ('your', 'Your', 'YOUR'):
        if word == 'Your':
            value = 1.45 if raw.startswith(' ') else 1.9
            if first:
                value = 4.8
        elif word == 'YOUR':
            value = 1.05
        elif not raw.startswith(' '):
            value = 1.0
        elif comma:
            value = 0.97
        elif p in COORDINATORS:
            value = 0.7
        elif p in {'to', 'with'}:
            value = 0.05
        else:
            value = 0.26
    elif word == 'YOU':
        value = 2.1
    elif word.lstrip('"“‘\'->') in ('You', 'you'):
        value = 2.4
    elif word in SECOND_PERSON:
        value = SECOND_PERSON[word]
    elif '你' in word or '您' in word:
        value = 0.35
    elif tail.endswith('คุณ') and raw.endswith('ณ'):
        value = 3.0
    elif word in ('There', 'there'):
        value = 0.63 if word == 'There' else (0.23 if clause else 0.03)
    elif prev in ('you', 'You'):
        capital = prev == 'You'
        if word in ('are', "'re", '’re'):
            value = (0.45 if capital else 0.33) * previous_value
        elif word in ('have', "'ve", '’ve'):
            value = (0.39 if capital else 0.32) * previous_value
        elif word in ('need', 'will'):
            value = (0.24 if word == 'need' else 0.16) * previous_value
        elif word == 'can':
            value = 0.1 if capital else -0.21
    return (doc, raw, value, n, tail), float(value)

