    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    if word == "You":
        value = 4.5
    elif word == "you":
        value = 2.5 if before in CLAUSE_BEFORE else 1.5
    elif word == "Your":
        value = 1.5
    elif word in ("your", "yours"):
        value = 0.3
    elif word in AUX_AFTER_YOU and before in YOU:
        value = 0.7
    elif word in FOREIGN_YOU:
        value = 1.5
    else:
        value = 0.0
    return carry, float(value)

