"""A local spelling-boundary approximation, strongest after an a-like vowel.

The response is positive for l/r onsets and negative for several other
consonants. Spaces and long tokens weaken it; other final vowels give
much weaker responses. Simple transliterations cover several alphabets.
The quantity phrases 'a lot/few/little/bit' are special cases. Split
UTF-8 characters are completed from the causal text prefix. This is
not a pronunciation parser, and ignores longer-range context.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
CYRILLIC = dict(zip('абвгдежзийклмнопрстуфхцчшщыэюяьъ',
                    'abvgdezzijklmnoprstufhccssieua__'))
GREEK = dict(zip('αβγδεζηθικλμνξοπρστυφχψω',
                'abgdezetiklmnxoprstufhpo'))
ARABIC = dict(zip('ابتثجحخدذرزسشصضطظعغفقكلمنهوي',
                 'abttjhhddrzsssdttagfqklmnhwi'))
HANGUL_ONSETS = ('g', 'g', 'n', 'd', 'd', 'r', 'm', 'b', 'b',
                 's', 's', 'a', 'j', 'j', 'c', 'k', 't', 'p', 'h')
# The 21 Hangul medial vowels grouped into five coarse vowel classes.
HANGUL_VOWELS = 'aeaeoeoeoaeoouoeiuuii'


def alphabet(c):
    name = ud.name(c, '') if c else ''
    for label, prefixes in (
        ('latin', ('LATIN', 'DIGIT')),
        ('cyrillic', ('CYRILLIC',)), ('greek', ('GREEK',)),
        ('arabic', ('ARABIC',)), ('hangul', ('HANGUL',)),
        ('kana', ('KATAKANA', 'HIRAGANA')),
        ('indic', ('DEVANAGARI', 'BENGALI', 'GURMUKHI', 'GUJARATI',
                   'ORIYA', 'TAMIL', 'TELUGU', 'KANNADA', 'MALAYALAM')),
        ('thai', ('THAI',)),
    ):
        if name.startswith(prefixes):
            return label
    return 'other'


def bare(c):
    return ''.join(x for x in ud.normalize('NFD', c.lower())
                   if ud.category(x) != 'Mn')[:1]


def onset_letter(c):
    if not c:
        return ''
    if 0xAC00 <= ord(c) <= 0xD7A3:
        return HANGUL_ONSETS[(ord(c) - 0xAC00) // 588]
    c = bare(c)
    if not c:
        return ''
    for transliteration in (CYRILLIC, GREEK, ARABIC):
        if c in transliteration:
            return transliteration[c]
    name = ud.name(c, '')
    if 'KANA LETTER ' in name or 'HIRAGANA LETTER ' in name:
        syllable = name.split('LETTER ')[1].replace('SMALL ', '').lower()
        return 's' if syllable.startswith('shi') else (
            'c' if syllable.startswith(('chi', 'tsu')) else syllable[0])
    # Indic letter names explicitly identify their consonant sound.
    if 'LETTER ' in name and alphabet(c) == 'indic':
        sound = name.split('LETTER ')[-1].lower()
        if sound in ('ra', 'rra', 'la', 'lla', 'llla', 'rha'):
            return 'r' if sound.startswith('r') else 'l'
        if sound in ('ba', 'bha', 'ka', 'kha', 'ga', 'gha',
                     'ma', 'pa', 'pha', 'ca', 'cha'):
            return sound[0]
    if alphabet(c) == 'thai':
        return {'ร': 'r', 'ล': 'l', 'ฬ': 'l', 'บ': 'b', 'ฟ': 'f',
                'ก': 'k', 'ค': 'k', 'ม': 'm', 'จ': 'c'}.get(c, '')
    return 'l' if c == 'ł' else '#' if c.isdigit() else c


def onset_strength(onset):
    # Coarse fitted response groups, not a word- or token-ID lookup.
    for letters, value in (
        ('lr', 2.8), ('b', -1.6), ('fgm', -0.9), ('ckphv', -0.6),
        ('dxo', -0.4), ('i', 0.35), ('t', 0.23), ('#', 0.14),
        ('ajswy', -0.15),
    ):
        if len(onset) == 1 and onset in letters:
            return value
    return {'ch': -1.7, 'qu': -1.7, 'sh': -0.4,
            'i-liquid': 1.9, 'e-liquid': 0.7, 'u-liquid': 0.7,
            'o-liquid': -0.3}.get(onset, 0.0)


def final_vowel_strength(text):
    if not text:
        return 0.0
    c = text[-1]
    name = ud.name(c, '')
    if c in 'َاأإآ' or c in 'าัะ' or 'VOWEL SIGN AA' in name:
        return 0.95 if alphabet(c) == 'arabic' else 1.0
    if 0xAC00 <= ord(c) <= 0xD7A3:
        vowel = HANGUL_VOWELS[((ord(c) - 0xAC00) % 588) // 28]
        return {'a': 0.52, 'e': 0.17, 'i': 0.01,
                'o': 0.16, 'u': 0.05}[vowel]
    if 'KANA LETTER ' in name or 'HIRAGANA LETTER ' in name:
        vowel = name.split('LETTER ')[1][-1].lower()
        return {'a': 0.51, 'e': 0.04, 'i': 0.0,
                'o': 0.05, 'u': -0.03}.get(vowel, 0.0)
    c0 = bare(c)
    if c0 in ('a', 'а', 'я', 'α'):
        if c in 'aA':
            return 1.0
        return {'latin': 0.77, 'cyrillic': 0.84,
                'greek': 0.70}.get(alphabet(c), 0.0)
    return {'e': 0.03, 'i': 0.01, 'o': 0.08,
            'u': 0.05}.get(onset_letter(c), -0.01)


@lru_cache(maxsize=65536)
def describe(text):
    word = text.lstrip()
    leading_space = len(word) != len(text)
    start = 0
    while start < len(word) and not word[start].isalnum():
        start += 1
    spelling = word[start:]
    onset = onset_letter(spelling[:1])
    if spelling[:1].isascii():
        lower = spelling.lower()
        if lower.startswith(('ch', 'sh', 'th', 'qu')):
            onset = lower[:2]
        elif len(lower) > 1 and lower[0] in 'aeiou' and lower[1] in 'rl':
            onset = lower[0] + '-liquid'
    n = len(spelling)
    bucket = 0 if n == 1 else 1 if n <= 3 else 2 if n <= 6 else 3
    attenuation = (1.0, 0.78, 0.47, 0.18, 0.34, 0.12, 0.074, 0.034)
    scale = attenuation[bucket + 4 * leading_space]
    scale *= 0.75 if start else 1.0
    scale *= {'latin': 1.0, 'cyrillic': 1.13, 'greek': 1.01,
              'arabic': 0.75, 'hangul': 0.85, 'kana': 1.01,
              'indic': 0.85, 'thai': 0.85}.get(
                  alphabet(word[:1]), 0.49)
    prior_scale = (1.0, 0.81, 0.73, 0.57, 0.48)[
        min(max(len(word) - 1, 0), 4)]
    return onset, scale, final_vowel_strength(text) * prior_scale


QUANTITIES = {' lot': 2.25, ' few': 0.29, ' little': 0.25, ' bit': -0.29}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    # Complete split UTF-8 characters only when a token decodes incompletely.
    if '\ufffd' in text:
        before = prefix.text_prefixes[-2] if prefix.position else ''
        after = prefix.text_prefixes[-1]
        text = after[len(before.rstrip('\ufffd')):]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    onset, scale, _ = describe(text)
    value = -0.013 if onset in ('l', 'r') else -0.001
    if previous:
        if previous.strip().lower() == 'a' and text in QUANTITIES:
            value = QUANTITIES[text]
        else:
            value += onset_strength(onset) * scale * describe(previous)[2]
    # Ignore NUL interleaving in UTF-16-like text, not document boundaries.
    if text and not text.strip('\x00'):
        return (doc, previous), float(value)
    return (doc, text), float(value)

"""Recognize short ri/li spellings across writing systems.

Whole syllables fire strongly, especially Japanese, Korean, and Chinese
forms. Longer pieces containing them get weaker responses. The numeric
strengths are training estimates, not universal pronunciation rules.
This deliberately leaves most weak, token-specific responses at zero.
"""
import re

READS = ()

# Mandarin li spellings; related characters do not have identical strengths.
CHINESE_LI = {
    '里': 3.37, '裏': 2.65, '裡': 2.38,
    '丽': 3.1, '麗': 2.25, '莉': 2.6,
    '李': 1.5, '利': 1.55, '理': 0.86,
    '梨': 0.63, '黎': 0.55, '离': 0.39, '離': 0.44,
}
SYLLABLES = {
    'リ': 4.15, 'り': 2.7, '리': 2.58,
    'ри': 0.88, 'ли': 0.6, 'ري': 0.75, 'لي': 0.7,
}
RI_AFTER_VOWEL = {'a': 0.85, 'e': 0.64, 'i': 1.25, 'o': 1.17, 'u': 1.6}
LI_AFTER_VOWEL = {'a': 0.54, 'e': 0.38, 'i': 0.7, 'o': 0.4, 'u': 0.28}


def spelling_value(text):
    s = text.strip()
    if s in SYLLABLES:
        return SYLLABLES[s]
    if s in CHINESE_LI:
        return CHINESE_LI[s]
    n = len(s)
    if any(c in '里裏裡' for c in s):
        if any(c in s for c in '这這那哪'):
            return 0.2  # here/there/where compounds
        if n == 2:
            return 1.7 if s[0] in '里裏裡' else 1.0
        return 0.35
    if any(c in CHINESE_LI for c in s):
        return 0.3 if n == 2 else 0.12
    if 'リ' in s:
        if n != 2:
            return 0.18
        if s.endswith('リ'):
            return 1.9
        if s.endswith('ー'):
            return 1.7
        return 0.55 if s.endswith('ン') else 1.1
    if 'り' in s:
        if n <= 3 and s.endswith('たり'):
            return 1.6 if s.startswith('っ') else 1.2
        if n == 2:
            if s == 'より':  # Japanese comparative particle
                return 0.0
            return 2.25 if s.startswith('く') else 0.6
        return 0.5 if n == 3 and s.endswith('り') else 0.05
    if '리' in s:
        if n == 2:
            return 1.25 if s.startswith('리') else 0.45
        return 0.0

    lower = s.lower().lstrip('._/-(')
    if re.fullmatch(r'[aeiou]?[rl][iy]', lower):
        if lower.endswith('ri'):
            v = RI_AFTER_VOWEL.get(lower[0], 0.56)
            return v * 0.65 if lower == 'uri' and s != lower else v
        if lower.endswith('li'):
            return LI_AFTER_VOWEL[lower[0]] if len(lower) == 3 else 0.4
        if len(lower) == 2 and text[:1].isspace():
            return 0.45
        if lower == 'ury':
            return 0.75
        return 0.27 if lower == 'ory' else 0.09
    if re.fullmatch(r'[aeiou]{1,2}ri[eas]s?', lower):
        return 0.32 if 'ria' in lower else 0.45
    if re.fullmatch(r'[a-z]{1,3}[rl]i', lower):
        return 0.25 if lower.endswith('ri') else 0.14
    if re.fullmatch(r'[аеёиоуыэюя][рл]и', lower):
        if lower == 'или' and text[:1].isspace():
            return 0.0  # the Russian function word "or"
        return 0.2 if lower == 'ели' else 0.55
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == '\ufffd':
        # A final UTF-8 byte can complete a liquid-consonant kana.
        if len(prefix.document_ids) < 2:
            return None, 0.0
        if prefix.document_ids[-2] != prefix.document_ids[-1]:
            return None, 0.0
        c = prefix.text_prefixes[-1][-1:]
        return None, {'リ': 5.35, 'ラ': 1.7, 'レ': 1.55, 'ル': 1.25}.get(c, 0.0)
    return None, float(spelling_value(s))

programs.luna:
"""Guess the small multilingual liquid-syllable feature at this MLP output.

It assigns a positive activation to visible li/ri-like token pieces. The estimate is
strongest for recurring Chinese and Japanese spellings; ordinary Latin spellings are a
much weaker clue.
"""

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()

    if "里" in token or "裡" in token or "裏" in token:
        return None, 2.0
    if "リ" in token:
        return None, 2.5
    if "レ" in token:
        return None, 0.3
    if "り" in token:
        return None, 0.45
    if "れ" in token:
        return None, 0.12
    if "리" in token:
        return None, 1.2
    if "利" in token or "理" in token:
        return None, 0.4
    if any(piece in token for piece in ("ри", "ли", "ري", "لي")):
        return None, 0.3
    if "ri" in token or "li" in token:
        return None, 0.03
    return None, 0.0

programs.sol:
"""A sparse lexical detector for term(s), item(s), and Chinese item counters.

These forms account for many large training activations. Predict a negative
response, strongest for 项/項; distinguish 'in terms', duration phrases,
algebraic modifiers, casing, and code punctuation. Carry a smaller response
onto a following preposition, resetting at document boundaries. Include weaker
responses to French/Spanish term words, Korean 항, options, and YAML extensions.
Everything else predicts zero: small token-specific background is not modeled.
"""

READS = ()

ALGEBRAIC = {
    'constant', 'constants', 'quadratic', 'cubic', 'squared',
    'cross', 'like', 'third', 'fourth',
}
# Lexicalized Chinese item compounds do not behave like the bare counter.
ITEM_COMPOUNDS = {
    '事项': -3.6,  # matters/items of business
    '专项': -2.4,  # special item/project
    '选项': -1.9,  # option
    '款项': -1.8,  # sum/item of money
    '单项': -5.2,  # single item
    '多项': -5.2,  # multiple items
    '奖项': -0.6,  # award
}
QUANTIFIED_ITEMS = {
    '一项', '两项', '三项', '四项', '这项', '此项', '的一项', '的各项',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    prior = previous.strip().lower()
    word = token.strip().lstrip('._-(/<$')
    lower = word.lower()
    value = 0.0

    if lower in {'term', 'terms'}:
        if fresh and token in {' term', ' terms'}:
            value = -4.28
        elif token.startswith('-'):
            value = -1.45
        elif word != lower:
            value = -2.85 if token == ' Terms' else -2.6
        elif token.startswith(' '):
            value = -3.35 if lower == 'term' else -2.9
            if lower == 'terms' and prior == 'in':
                value = -2.25
            elif lower == 'term' and prior in {'long', 'short', 'near'}:
                value = -2.1
            elif prior in ALGEBRAIC:
                value = -4.0 if lower == 'term' else -3.5
            elif prior == 'the':
                value -= 0.25
        else:
            value = -2.15
    elif lower in {'item', 'items'}:
        if token.startswith(' '):
            value = -1.4 if lower == 'item' else -1.5
            if word == 'Item':
                value = -1.25
        elif token.startswith(('(', '<', '\t')):
            value = -0.9
        elif token.startswith('-'):
            value = -2.3
        elif word == 'Item':
            value = -1.55
        elif token.startswith('_'):
            value = -1.3
        else:
            value = -1.1
    elif word in {'getItem', 'getItems', 'setItem', 'setItems', 'ListItem'}:
        value = -1.35 if word in {'getItem', 'ListItem'} else -0.85
    elif token == 'omial':
        value = -2.0 if 'mult' in prior else -1.5
    elif token.strip() in {'项', '項'}:
        value = -7.4 if '项' in token else -6.5
    elif token in {'各项', '该项'}:
        value = -8.5
    elif token in QUANTIFIED_ITEMS:
        value = -6.8
    elif token == '是一项':
        value = -5.9
    elif token in ITEM_COMPOUNDS:
        value = ITEM_COMPOUNDS[token]
    elif token.strip() in {'项目', '項目'}:
        value = -1.0 if '项' in token else -2.2
    elif token.strip() == '항':
        value = -4.0 if token.startswith(' ') else -3.0
    elif word in {'terme', 'término'}:
        value = -1.2
    elif lower in {'option', 'options'}:
        value = -0.4
    elif token in {'.yaml', '.yml'}:
        value = -0.83 if token == '.yaml' else -0.28
    elif prior in {'term', 'terms'}:
        if token == ' of':
            value = -0.95 if prior == 'term' else -0.78
        elif token in {' in', ' with'}:
            value = -0.23 if token == ' in' else -0.44

    return (doc, token), value

programs.haiku:
"""Term / item detector (v3): the word 'term' is strongest in its mathematical sense."""
import re
READS = ()

def _word(s):
    return re.sub(r"[\s\-_.(]", "", s).lower()

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = _word(s)
    prev = _word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if w in ("term", "terms"):
        if prev in ("long", "short", "longer"):
            return carry, -1.6
        if prev == "in":
            return carry, -2.2
        return carry, -3.4
    if w in ("item", "items"):
        return carry, -1.4
    if w in ("option", "options"):
        return carry, -0.4
    if w in ("omial", "nomial"):
        return carry, -1.8
    if len(s) <= 3 and s[-1:] in ("项", "項"):
        return carry, -6.5
    if s == "项目" or s == "項目":
        return carry, -1.0
    if w == "of" and prev in ("term", "terms"):
        return carry, -0.9
    return carry, 0.0

programs.sol:
"""Approximate a response to time relations and calendar-date boundaries.

Before/after words respond most strongly just after a duration. A month name
has a smaller response itself, then a large negative response on the
following separate space. A short date state supplies diminishing responses to
its digits and later spaces. Some prepositions following time nouns are
positive. These are text heuristics, not a general parser of temporal meaning.
"""
READS = ()
MONTHS = set('January February March April May June July August September '
             'October November December'.split())
SHORT_MONTHS = set('Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec'.split())
UNITS = set('second seconds minute minutes hour hours day days week weeks '
            'month months year years decade decades time period season'.split())
DATE_LABELS = set('year years month week day season spring summer autumn fall '
                  'winter early late age aged'.split())
BASE = {'after': -1.0, 'before': -0.27, 'later': -0.15, 'prior': -0.12,
        'since': -0.08, 'until': -0.14, 'when': -0.04, 'past': -0.25,
        'starting': -0.30, 'beginning': -0.30, 'period': -0.15,
        'anniversary': -0.8, 'elapsed': -1.05, 'thereafter': -1.2,
        'afterwards': -0.6, 'ago': -0.25, 'next': -0.11}
RELATIVE = {'after': -3.1, 'before': -1.6, 'later': -2.3, 'prior': -2.35,
            'since': -1.3, 'following': -1.65, 'when': -0.85,
            'until': -0.9, 'earlier': -1.7, 'period': -1.4,
            'periods': -1.4, 'interval': -1.35, 'intervals': -1.35,
            'point': -1.4, 'points': -1.1, 'stamp': -0.85}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    _, previous, strength, age = (doc, '', 0.0, 100) if start else carry
    token = prefix.token_strings[-1]
    name = token.strip().strip('._-()')
    word = name.lower()
    value = BASE.get(word, 0.0)
    if word in {'elapsed', 'ago'} and not token.startswith(' '):
        value = 0.0
    if word in {'year', 'years', 'day', 'days', 'season'}:
        value = 0.09
    if name[:1].isupper() and word in {'before', 'when', 'after'}:
        value = -0.8 if word == 'after' else 0.04
    if previous in UNITS and token.startswith(' '):
        value = RELATIVE.get(word, value)
        if previous in {'time', 'second', 'seconds', 'minute', 'minutes',
                        'hour', 'hours'}:
            if word == 'after':
                value = -2.4
            elif word == 'later':
                value = -1.2
        if word in {'in', 'on', 'with'}:
            value = 0.35
    if previous in {'immediately', 'shortly', 'just', 'long', 'ever'}:
        if word == 'after':
            value = -2.2
        elif word == 'before':
            value = -1.0
    if word == 'of':
        if previous in {'end', 'beginning', 'time', 'week', 'days', 'months'}:
            value = -0.45
        elif previous in {'month', 'anniversary'}:
            value = -1.0
        elif previous in {'year', 'years', 'day'}:
            value = -0.20
    if word == 'to' and previous == 'prior':
        value = -0.6
    if word == 'past' and previous == 'the':
        value = -0.8
    if previous in {'after', 'before', 'during', 'until'} and word in {
            'the', 'this', 'that', 'a', 'an', 'his', 'her', 'it'}:
        value = -0.25 if word in {'the', 'this', 'that'} else -0.13
    if word == 'zone' and previous == 'time':
        value = 0.42
    if word == 'old' and previous.strip('-') == 'year':
        value = 0.55

    full = (name in MONTHS or
            (name.title() in MONTHS and word not in {'may', 'march'}))
    if full or name in SHORT_MONTHS:
        strength = 1.65 if full else 1.05
        strength -= 0.2 * (not token.startswith(' '))
        value = (-0.44 if full else -0.08) if token.startswith(' ') else -0.18
        if name == 'May':
            value, strength = -0.14, 1.2
        age = 0
    elif word in DATE_LABELS:
        strength, age = 0.75, 0
    else:
        age += 1
        if not (name.isdigit() or token in {' ', ',', '.', '-', '/', 'th'}):
            strength = 0.0
        if strength and age <= 8:
            if token == ' ':
                fade = (1.0 if age == 1 else 0.6 if age == 2 else
                        0.3 if age <= 5 else 0.08)
                value = -strength * fade
            elif name.isdigit():
                fade = 0.23 if age == 2 else 0.1 if age == 3 else 0.03
                value = -strength * fade * (0.3 if name == '0' else 1.0)
    # East Asian month markers precede day digits without a space.
    if token in {'月', '월'}:
        value = -0.85 if previous.isdigit() else -0.20
        strength, age = 1.1, -1
    if previous in {'月', '월'} and name.isdigit():
        value = -0.95
    if previous == '年' and name.isdigit():
        value = -0.5
    if token in {'前', '后', '後', '之后', '以前', '前后', '間', '半', '末'}:
        time_unit = previous.endswith(('年', '月', '週', '日', '天', '時間'))
        value = -1.4 if time_unit else -0.2
    # Cropped rows and new documents have stronger initial time-word responses.
    if start:
        value = {'after': -1.85, 'before': -1.4, 'when': -0.4,
                 'year': -1.35, 'day': -0.76, 'period': -1.95}.get(word, value)
    return (doc, word, strength, age), float(value)

programs.luna:
"""Predicts negative responses to temporal links and dates.

The strongest examples occur on words such as “after” and “before,” and on
the space that starts a day after a month name.  This small rule recognizes
those surface forms rather than trying to reconstruct the model's hidden state.
"""

READS = ()

MONTHS = {
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept",
    "oct", "nov", "dec",
}
TEMPORAL = {
    "after", "before", "until", "prior", "when", "while", "since",
    "next", "last", "then", "formerly", "later", "earlier", "following",
    "previous", "final", "eventually", "day", "days", "week", "weeks",
    "month", "months", "year", "years", "today", "tomorrow", "yesterday",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold().strip(".,:;!?()[]{}\"'“”‘’")
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().casefold().strip(".,:;!?()[]{}\"'“”‘’")

    if word in {"after", "before", "when"}:
        return None, -0.85
    if word in {"until", "prior", "since", "following", "previous", "later", "earlier", "next", "last", "final"}:
        return None, -0.45
    if word in MONTHS:
        return None, -0.30
    if token.isspace() and previous in MONTHS:
        return None, -1.0
    if word in {"day", "days", "week", "weeks", "month", "months", "year", "years", "today", "tomorrow", "yesterday", "then", "while", "formerly", "eventually"}:
        return None, -0.20
    return None, 0.0

"""Predict small activations on calculation language in a math discussion."""

READS = ()

CALCULATION_MOVES = {
    "let", "write", "written", "compute", "calculate", "substitute",
    "assume", "denote", "solve", "starting", "adding", "plug", "cancel",
}
MATH_WORDS = {
    "expression", "equation", "variable", "variables", "modulus", "mod",
    "numerator", "denominator", "polynomial", "multiplication", "factor",
    "term", "terms", "formula", "formulas", "scalar", "residue", "step",
}
EXPLANATION_WORDS = {"we", "me", "us", "now", "see", "get", "can", "for", "by", "need", "think"}
MATH_HINTS = ("=", "$", "√", "∑", "Σ", "equation", "variable", "formula", "polynomial", "factor", "mod")


def step(carry, prefix, upstream):
    current_doc = prefix.document_ids[-1]
    prior_text = ""
    if carry is not None and carry[0] == current_doc:
        prior_text = carry[1]
    token = prefix.token_strings[-1]
    recent = (prior_text + token)[-160:]
    next_carry = (current_doc, recent)

    # Ignore standalone punctuation, or it could repeat the previous word's cue.
    if not any(char.isalpha() for char in token):
        return next_carry, 0.0

    end = len(recent) - 1
    while end >= 0 and not recent[end].isalpha():
        end -= 1
    start = end
    while start >= 0 and recent[start].isalpha():
        start -= 1
    word = recent[start + 1 : end + 1].lower()
    math_discussion = any(char.isdigit() for char in recent)
    math_discussion |= any(hint in recent for hint in MATH_HINTS)

    if math_discussion and word in CALCULATION_MOVES:
        return next_carry, 0.45
    if math_discussion and word in MATH_WORDS:
        return next_carry, 0.30
    if math_discussion and word in EXPLANATION_WORDS:
        return next_carry, 0.25
    return next_carry, 0.0

"""Recognize low-level computing terms, requiring local context for common words."""

READS = ()

DIRECT = frozenset({
    "bhyve", "clk", "ctl", "dos", "dsp", "floppy", "hardware", "ipc",
    "interrupt", "kernel", "中断", "nand", "overlay", "packet", "pci",
    "pcm", "ram", "usb", "vulkan",
})
CONTEXTUAL = frozenset({
    "analog", "audio", "boot", "bus", "card", "clock", "cpu", "device",
    "disk", "drive", "flash", "graphics", "memory", "mouse", "platform",
    "processor", "video", "vm", "driver", "drivers", "mc", "trailing",
})
CUES = frozenset({
    "alignment", "analog", "audio", "computer", "controller", "device",
    "digital", "disk", "display", "drive", "dsp", "filter", "flash",
    "floppy", "graphics", "group", "hardware", "image", "interface", "java",
    "kernel", "layout", "memory", "nand", "nfc", "network", "packet", "pci",
    "pcm", "processor", "ram", "register", "screen", "storage", "subtitle",
    "system", "usb", "video", "vulkan",
})
EDGE = " \t\r\n.,;:!?/\\_()[]{}<>\"'`*+-=|"


def _parts(text):
    part = ""
    for char in text.lower():
        if char.isalnum():
            part += char
        elif part:
            yield part
            part = ""
    if part:
        yield part


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(EDGE).lower()
    if word in DIRECT:
        return None, -0.18
    if word in CONTEXTUAL:
        recent = prefix.token_strings[max(0, len(prefix.token_strings) - 10):-1]
        neighbors = {part for token in recent for part in _parts(token)}
        if any(part in CUES for part in neighbors):
            return None, -0.18
    return None, 0.0

