"""Component layers.0.mlp.down_proj:220: a "task instruction" detector, with a
judging/capability sign.

Negative where the text is giving or doing a task:
- the verb that opens an instruction ("Describe the...", "1. Explain...", "- Identify..."),
  strongly for the most common instruction verbs, weakly when the same verb is mid-sentence;
- other task-work words ("planning", "brainstorm", "organize", "clearly", "accurately").
Mildly positive on nouns for judging and capability ("comparison", "interpretation",
"judgment", "imagination", "abilities").
Everything else is predicted as 0. Most of the component's variance is diffuse token-level
noise that no word list captures, so these rules explain only a small share of it.
"""

READS = ()

# Verbs that open a task or assignment, as in a worksheet or a learning objective.
STRONG_TASK_VERBS = {"explain", "describe", "discuss", "define", "identify"}
TASK_VERBS = {
    "compare", "analyze", "analyse", "communicate", "demonstrate", "summarize",
    "outline", "develop", "prepare", "provide", "give", "draw", "write", "assess",
    "classify", "organize", "brainstorm",
}
# Other words of planning, communicating and doing a task carefully (mildly negative).
TASK_WORDS = {
    "planning", "explaining", "identifying", "clearly", "carefully", "accurately",
    "accurate", "documentation", "descriptive", "meaningful", "teamwork",
}
# Nouns and adjectives for judging, understanding and capability (mildly positive).
JUDGING_WORDS = {
    "comparison", "interpretation", "evaluation", "evaluate", "judgment", "imagination",
    "grasp", "comprehend", "ability", "abilities", "capability", "capabilities", "details",
    "counts", "plot",
}
# Tokens after which a word starts a new sentence, bullet or numbered item.
BOUNDARY = ("\n", ".", ":", "!", "?", "•", "-", "*", ")")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    starts_item = before.strip() == "" or before.rstrip().endswith(BOUNDARY) or before.strip().isdigit()
    capitalised = token.strip()[:1].isupper()
    if word in STRONG_TASK_VERBS:
        value = -0.33 if (capitalised and starts_item) else -0.1
    elif word in TASK_VERBS:
        value = -0.2 if (capitalised and starts_item) else -0.08
    elif word in TASK_WORDS:
        value = -0.12
    elif word in JUDGING_WORDS:
        value = 0.1
    else:
        value = 0.0
    return carry, float(value)

"""layers.0.mlp.down_proj:222 as a "t-sound fragment" detector.

This MLP output unit is mostly a function of the current token's spelling. It goes
negative on the letter t when it closes a syllable or stands alone: the words "it",
"at", "its", "they", "their", fragments such as "t", "et", "ot", and other ASCII
word-pieces that end in t (about -0.6) or have a t inside (about -0.3). A t at the
start of a word ("test", "toArray"), a "th", an "st" and most common English words
("that", "but", "first", "about") stay near zero. Tokens written in other scripts
with no ASCII letters get a small negative value. Everything else is 0.

The program is stateless: it reads only the newest token.
"""

READS = ()

CORE = {"it", "its", "at", "t", "et", "ot", "they", "their"}
COMMON = {"that", "but", "what", "with", "not", "about", "out", "most", "must", "just", "first", "last", "least", "right", "the"}


def _value(token: str) -> float:
    word = token.strip().lower()
    if word in CORE:
        return -1.2
    if word in COMMON or not word:
        return 0.0
    if word.isascii() and word.isalpha():
        if "t" not in word or word[0] == "t":
            return 0.0
        if word.endswith("t"):
            return 0.0 if word.endswith("st") else -0.6
        inner = [i for i in range(1, len(word)) if word[i] == "t" and word[i - 1] != "s" and word[i + 1 : i + 2] != "h"]
        return -0.3 if inner else 0.0
    if not any(c.isascii() and c.isalpha() for c in word) and any(c.isalpha() for c in word):
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(_value(prefix.token_strings[-1]))

"""Points of the compass used in place names switch this component on, negatively:
North, South, East, West (any case, with or without a leading space, and the
word-pieces 'orth'/'outh' that split North/South), the Chinese compass characters
南北東西, and compounds like northeast. Weaker negative responses come at regional
adjectives (western, central, Nord) and at capitalised first words of some place names
(New, San, United). Everything else is about zero."""
READS = ()

COMPASS = {"north": -8.5, "south": -9.0, "east": -6.5, "west": -7.0}
CHINESE = {"南": -7.5, "北": -7.5, "西": -5.5, "東": -3.5, "东": -3.0}
COMPOUND = {"northeast", "northwest", "southeast", "southwest", "northeastern",
            "northwestern", "southeastern", "southwestern", "northern", "southern"}
REGIONAL = {"western", "eastern", "central", "nord", "sud"}
PLACE_OPENERS = {"New": -0.5, "San": -1.0, "Santa": -1.0, "Saint": -0.8, "United": -0.7,
                 "States": -0.5, "Mexico": -1.0, "Europe": -1.0}

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip().lower().strip("-")
    if s in COMPASS:
        return None, COMPASS[s]
    if raw.strip() in ("orth", "outh"):
        return None, -4.0
    if s in COMPOUND:
        return None, -4.0
    if s in REGIONAL:
        return None, -2.5
    if raw.strip() in PLACE_OPENERS:
        return None, PLACE_OPENERS[raw.strip()]
    if s in CHINESE:
        return None, CHINESE[s]
    return None, 0.0

