programs.sol:
"""Leading-digit magnitude, with familiar number-format corrections.

The first digit of a number is increasingly negative from 1 to 8, then
saturates. Later adjacent digits are quiet. Fractional digits and fields in
numeric lists are weaker; newlines and opening delimiters strengthen the
response. Number words have a smaller, mostly similar response. This predicts
a leading digit, not the value of the complete (possibly unfinished) number.
"""
READS = ()
DIGITS = '0123456789'
WIDE_DIGITS = '０１２３４５６７８９'
NARROW = str.maketrans(WIDE_DIGITS, DIGITS)
CARDINALS = 'zero one two three four five six seven eight nine'.split()
ORDINALS = (
    'zeroth first second third fourth fifth sixth seventh eighth ninth'
).split()
WORDS = (
    -0.06, 0.0, 0.12, -0.06, -0.40, -0.60, -0.66, -0.75, -0.75, -0.62
)
CHINESE = '零一二三四五六七八九'
CHINESE_VALUES = (
    0.04, 0.12, 0.25, -0.12, -0.48, -0.95, -0.85, -0.90, -0.80, -0.42
)


def digit_response(n, previous, before):
    if not previous:
        return 0.0
    if previous[-1] in DIGITS:
        return -0.04 if n == 1 else 0.02
    # Almost linear through four; it then flattens toward eight and nine.
    base = 0.17 - 0.382*n + 0.041*max(n - 4, 0)**2
    if '\n' in previous:
        return base - 1.02
    after_number = bool(before) and before[-1] in DIGITS
    if after_number:
        if previous == '.':
            return 0.12 + 0.38*base
        if previous == ',' or previous.isspace():
            return 0.02 + 0.56*base
        if previous == ':':
            return -0.24 + 0.82*base
        if previous[-1] in '+−-/':
            return -0.10 + 0.92*base
    if previous.isspace():
        if '\u00a0' in previous or '\t' in previous:
            return -0.55 + 0.90*base
        return base - (0.20 if before.isspace() else 0.0)
    p = previous.strip()
    last = p[-1]
    if '\\x' in p or (before.endswith('\\') and p.startswith('x')):
        return 0.67 + 0.35*base
    if last in '([{':
        return base - 0.40
    if last in "'\"`":
        return base - 0.90
    if last in '$€£¥₹':
        return base - 0.60
    if last == '^':
        return base + 0.54
    if last in '+−-':
        return 1.12*base
    if last in '=≈≃':
        return -0.26 + 0.91*base
    if last == '.':
        return -0.19 + 0.76*base
    if last == '_':
        return base + (0.10 if p == '_' else -0.60)
    if len(p) == 1 and p.isascii() and p.isalpha():
        return 0.40 + 0.74*base if p in 'abcdef' else 0.18 + 0.94*base
    if p.isascii() and any(c.isalpha() for c in p):
        return base + 0.05
    if last.isalpha():
        return -0.48 + 1.12*base
    return -0.40 + 0.95*base


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = '', ''
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if len(token) == 1 and token in DIGITS + WIDE_DIGITS:
        wide = token in WIDE_DIGITS
        n = WIDE_DIGITS.index(token) if wide else int(token)
        value = digit_response(
            n, previous.translate(NARROW), before.translate(NARROW)
        )
        if wide:
            value -= 0.20
    elif word in CARDINALS or word in ORDINALS:
        ordinal = word in ORDINALS
        n = (ORDINALS if ordinal else CARDINALS).index(word)
        value = WORDS[n] * (0.82 if ordinal else 1.0)
        if n >= 4 and token.strip()[0].isupper() and not ordinal:
            value += 0.12
    elif len(token) == 1 and token in CHINESE:
        value = CHINESE_VALUES[CHINESE.index(token)]
    elif token == '³':
        value = -0.40
    elif token in ('₁', '₂'):
        value = -0.16
    return (doc, token, previous), float(value)

programs.haiku:
"""First digit of a number, scaled by context; document-aware."""
READS = ()

DIGITS = "0123456789"
FULLWIDTH = "０１２３４５６７８９"

def _value(tok):
    """The digit's value if tok is one digit (ASCII or fullwidth), else -1."""
    if len(tok) != 1:
        return -1
    if tok in DIGITS:
        return DIGITS.index(tok)
    if tok in FULLWIDTH:
        return FULLWIDTH.index(tok)
    return -1

def _scale(before, before2):
    """How strongly the token before the number scales it."""
    if before == "." and _value(before2) >= 0:
        return 0.3  # decimal fraction, as in 3.5
    if "\n" in before:
        return 1.85  # start of a line
    if any(c in before for c in "([{:=$_"):
        return 1.35  # after a bracket, colon or operator
    if before == ",":
        return 0.7
    if before and before[-1].isalpha():
        return 0.85  # inside or after a word
    return 1.1

def step(carry, prefix, upstream):
    digit = _value(prefix.token_strings[-1])
    n = len(prefix)
    if digit < 0:
        return None, 0.0
    new_doc = n == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if not new_doc and _value(prefix.token_strings[-2]) >= 0:
        return None, 0.0  # a later digit of a number, not the first
    before = "" if new_doc else prefix.token_strings[-2]
    before2 = "" if n < 3 or prefix.document_ids[-3] != prefix.document_ids[-1] else prefix.token_strings[-3]
    return None, -0.3 * min(digit, 7) * _scale(before, before2)

programs.sol:
"""A token-boundary opening-parenthesis detector, with local syntax effects.

A space followed by an opening parenthesis is strongly negative, especially
following a longer or capitalized alphabetic token. Arithmetic symbols and
named control-flow words weaken that response. A bare opening parenthesis is weaker still. Parentheses
already fused with their contents usually contribute little. Fullwidth opening
parentheses also respond; tokens containing '(' and ending in '!' have the
opposite sign. Other tokens are zero, except for a small positive square-bracket
response. Only the preceding token within the same document is consulted.
"""
READS = ()

FUNCTION_WORDS = frozenset('''
a an the as at by in of on to from with is are was were be been being
'''.split())
LOGICAL_WORDS = frozenset('and or not'.split())
CONDITIONAL_WORDS = frozenset('if elif'.split())
LOOP_WORDS = frozenset('for foreach switch'.split())
MATH_FUNCTIONS = frozenset('sin cos tan log ln exp sqrt min max'.split())


def isolated_opening(token, previous):
    """Approximate local syntax using the preceding token's text and shape."""
    word = previous.strip()
    if token == '(':
        if not previous:
            return 0.065
        if '\n' in previous:
            return -0.32
        if previous.isspace():
            return -0.23
        if word in MATH_FUNCTIONS:
            return -0.04
        return -0.12 if word.isalpha() else -0.20
    if not previous:
        return -0.44
    if previous.isspace():
        return -0.53
    if word.isalpha():
        if word in CONDITIONAL_WORDS:
            return -0.24
        if word == 'while':
            return -0.40
        if word in LOOP_WORDS:
            return -0.62
        if word in LOGICAL_WORDS:
            return -0.52
        if word in FUNCTION_WORDS:
            return -0.66
        value = -0.70 - 0.04 * min(len(word), 5)
        if word[0].isupper():
            value -= 0.10
        return value
    if word.isdigit():
        return -0.73
    if any(c in word[-3:] for c in ')]}'):
        return -0.49
    if word.endswith(tuple('+-=*/^')):
        return -0.62
    if word.endswith(tuple('\"\'`”')):
        return -0.90
    return -0.78


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    if '（' in token:
        return None, -0.67
    if '(' not in token:
        return None, 0.03 if '[' in token else 0.0
    if token.endswith('('):
        if token.strip() == '(':
            return None, isolated_opening(token, previous)
        if token.count('(') > 1:
            return None, -0.83
        if token.rstrip('(').endswith((')', '}')):
            return None, -0.23
        return None, -0.61
    if token.endswith('!'):
        return None, 0.47
    if token.startswith(' ('):
        if ')' in token:
            return None, -0.10
        if '\\' in token:
            return None, -0.46
        if any(c in token for c in '\"\'“'):
            return None, -0.21
        if '\n' in token:
            return None, -0.21
        return None, -0.07
    if token.strip() == '(\\':
        return None, -0.23
    if token.startswith('('):
        return None, 0.01
    return None, -0.18

"""Approximate a mixed UI / ui-spelling / waiting response.

The strongest negative values are for UI and GUI abbreviations. Short
ui syllables and ui-containing function words also respond, regardless
of whether the text discusses software. Interface words, GUI libraries,
and 'wait' are weaker branches. Predictions use the current token only;
the many small responses to other words are left at zero.
"""
READS = ()

# Short function words with the spelling ui (French, Italian, and Latin).
UI_WORDS = {
    'lui': -2.5, 'qui': -1.2, 'cui': -1.75, 'sui': -1.3,
    'celui': -0.6, 'suis': -0.72, 'puis': -0.9, 'oui': -0.95,
}
SHORT_VOWEL_CLUSTERS = {
    'uy': -0.8, 'ei': -0.8, 'oi': -0.4, 'ua': -0.2,
    'уй': -0.85, 'ου': -0.5,
}
GUI_LIBRARIES = {
    'qt', 'ttk', 'pygame', 'javafx', 'vue', 'jsx', 'reactstrap',
}


def token_value(token):
    clean = token.strip().lstrip('._-/(')
    word = clean.lower()
    if word == 'ui':
        value = -5.7 if clean == 'UI' else -3.55 if clean == 'Ui' else -4.9
        if clean == 'ui' and token.startswith(('.', '_', '-')):
            value = -5.5
        return value * 0.7 if token.startswith('(') else value
    if word.endswith('gui'):
        if word != 'gui':
            return -2.3  # Other gui endings, including GUI library names.
        return -4.9 if clean == 'Gui' and token[:1].isspace() else -4.3
    if word == 'mui':
        return -3.7
    if word in UI_WORDS:
        return UI_WORDS[word]
    if word in SHORT_VOWEL_CLUSTERS:
        return SHORT_VOWEL_CLUSTERS[word]
    if word in {'uis', 'uí', 'dui'}:
        return -1.5
    if (word.startswith('ui') and len(word) <= 4
            and word not in {'uint', 'uing', 'uild', 'uity'}
            or word.endswith('ui') and len(word) <= 5
            or word in {'uya', 'uuid', 'suiv', 'guit'}):
        return -0.75
    if clean.startswith('UI') and word != 'uint':
        return -1.2
    if word == 'cli':
        return -1.0 if token[:1].isspace() and clean != 'CLI' else -0.7
    if word in {'interface', 'interfaces', '界面'}:
        return -1.3 if word == '界面' else -0.82 if word.endswith('s') else -0.65
    if word in {'tkinter', 'pyqt', 'vaadin'}:
        return -1.6
