"""A syllable-based approximation, dominated by Japanese katakana /a/.

Single katakana syllables ending in /a/ get large positive values; several
/u/ syllables are negative. Byte-split /a/ characters get a further boost,
especially after a long-vowel mark. Longer kana tokens are attenuated, with
special rules for small kana and leading length or gemination marks.
Hiragana, open Hangul syllables, and Chinese /a/ transcription characters
have smaller responses. Everything else is zero; this intentionally leaves
unexplained the component's weaker, scattered responses in other text.
"""

READS = ()

# The five columns of the Japanese syllabary, with voiced and small forms.
VOWELS = (
    'アカサタナハマヤラワガザダバパァャヮヵ',
    'イキシチニヒミリヰギジヂビピィ',
    'ウクスツヌフムユルグズヅブプゥュヴ',
    'エケセテネヘメレヱゲゼデベペェヶ',
    'オコソトノホモヨロヲゴゾドボポォョ',
)


HANGUL_INITIALS = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'
HANGUL_VOWELS = (
    'a', 'ae', 'ya', 'yae', 'eo', 'e', 'yeo', 'ye', 'o', 'wa', 'wae',
    'oe', 'yo', 'u', 'wo', 'we', 'wi', 'yu', 'eu', 'ui', 'i',
)


def katakana(c, split=False):
    if c in VOWELS[0]:
        value = 2.3
        if c in 'サタバ':
            value = 4.3
        elif c in 'ガザダ':
            value = 3.2
        elif c in 'アハ':
            value = 1.6
        if split:
            value += 1.5
            if c in 'カパラ':
                value += 1.5
            elif c in 'サタナ':
                value -= 1.0
        return value
    if c in VOWELS[1]:
        if c == 'チ':
            return -0.1
        return 0.65 if c in 'イヒ' else 1.3
    if c in VOWELS[2]:
        return -0.5 if c in 'ツフムルブ' else 0.2
    if c in VOWELS[3]:
        if c in 'ケセデ':
            return 1.6
        return 0.5 if c in 'メレベペ' else 1.0
    if c in VOWELS[4]:
        if c in 'トド':
            return 0.0
        return 0.65 if c in 'ロゴ' else 1.2
    if c == 'ー':
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    split = '�' in s
    if split:
        # Joined decoding recovers a character whose earlier bytes were in
        # previous tokens. An unfinished next character is not counted yet.
        text = prefix.text_prefixes[-1]
        same_document = (
            prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]
        )
        if same_document and text and text[-1] != '�':
            s = text[-1]
        else:
            s = s.replace('�', '')
    if s and all('\u30a0' <= c <= '\u30ff' for c in s):
        if len(s) == 2 and s[-1] in 'ァィゥェォャュョ':
            value = katakana(s[-1])
        elif len(s) > 1:
            value = 0.5 * sum(katakana(c) for c in s) / len(s)
            if s[0] in 'ーッ':
                value = katakana(s[-1]) - 0.6
        else:
            value = katakana(s, split)
            if split and s in VOWELS[0] and text[-2:-1] == 'ー':
                value += 0.8
        if split and s.endswith('ー'):
            value = 1.0
        return None, float(value)
    if len(s) == 1 and '\u3041' <= s <= '\u3096':
        k = chr(ord(s) + 0x60)
        if s in 'がはのでにをも':
            return None, -0.05
        if s in 'さざなまわ':
            return None, 0.95
        if s in 'じゆよゃょ':
            return None, 0.65
        if s in 'ちつふ':
            return None, -0.3
        return None, float(0.13 * katakana(k))
    # Hangul encodes onset, vowel and optional final consonant in each
    # syllable. Open /a/ and /eo/ syllables show a smaller related response.
    if len(s) == 1 and '가' <= s <= '힣':
        code = ord(s) - ord('가')
        onset = HANGUL_INITIALS[code // 588]
        vowel = HANGUL_VOWELS[code // 28 % 21]
        final = code % 28
        if final:
            return None, -0.05 if vowel == 'eu' else 0.0
        if s in '가이의에':
            return None, 0.0
        value = {'a': 0.7, 'eo': 0.8, 'i': 0.35, 'o': 0.25,
                 'e': 0.3, 'eu': -0.3}.get(vowel, 0.0)
        if vowel == 'eo' and onset in 'ㅋㅌㅍ':  # aspirated k, t, p
            value += 0.5
        return None, float(value)
    # Familiar Chinese characters used to transcribe foreign /a/ syllables.
    if len(s) == 1:
        if s in '萨薩':
            return None, 1.9
        if s in '塔帕':
            return None, 1.1
        if s in '卡玛瑪巴拉纳納达達哈':
            return None, 0.65
        if s in '马馬亚亞娜':
            return None, 0.3
    return None, 0.0

