"""Privative ("without") detector for layers.0.mlp.down_proj:232.

This component is a "lacking / without" feature. It fires on the word piece that makes a
stem mean "without X":
  * the suffix "-less" as its own token ("life|less", "mass|less", "help|less"): strongest;
  * whole words ending in -less that mean "without X" ("endless", "harmless", "wireless");
  * "-free" ("sugar-free"), " free", " without", " nothing", " regardless", " impossible";
  * Chinese 无 / 無 ("without": 无线, 无私, 毫无), and weaker 不 / 没 ("not/no");
  * a weak response to English words in un- (" unstoppable", " unable").
Words in -less that are not privative ("unless", "nevertheless") and the comparative
" less" get little or nothing. The program reads only the newest token's text.
"""

READS = ()

LESS_SUFFIX = ("less", "lessly", "lessness", "-less")  # bare suffix tokens (no leading space)
NOT_PRIVATIVE = ("unless", "nevertheless", "nonetheless", "bless", "less")
UN_COMMON = ("under", "until", "union", "united", "unit", "units", "unique", "universal",
             "university", "unlike", "unfortunately", "unite", "unity", "update", "unto")
CJK_WITHOUT = "无無"    # "without"
CJK_NOT = "不没沒"       # "not / no"
JP_NONE = ("なし", "なく", "ない", "いない")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if not s.startswith(" ") and s.lower() in LESS_SUFFIX:
        return carry, 6.5
    if w in NOT_PRIVATIVE:
        return carry, 0.7 if s == " less" else 0.0
    if w.endswith("less") and len(w) >= 5:
        return carry, 3.0
    if any(c in CJK_WITHOUT for c in s):
        return carry, 4.0
    if w in ("regardless", "impossible", "infinite", "nothing"):
        return carry, 1.5
    if w in ("free", "without") or s == "-free":
        return carry, 2.0 if s == "-free" else 1.0
    if any(c in CJK_NOT for c in s) or any(p in s for p in JP_NONE):
        return carry, 1.0
    if s.startswith(" un") and w.isalpha() and len(w) >= 5 and w not in UN_COMMON:
        return carry, 0.35
    return carry, 0.0

