"""A spelling detector for doubled consonants, strongest for short 'ss' pieces.

Length, neighboring vowels, capitalization and word boundaries set the strength.
Other consonant pairs respond mainly at token endings. Sharp-s, Cyrillic doubled
s, katakana small tsu and Arabic shadda are related spelling signals. There are
also weaker matches to -ash endings, escaped dollars and doubled brackets.
A small echo continues into the next word piece; document boundaries reset it.
"""

READS = ()
PAIR_STRENGTH = {
    't': 0.7, 'n': 0.62, 'm': 0.4, 'p': 0.55, 'c': 0.8, 'r': 0.5,
    'f': 0.3, 'b': 0.6, 'g': 0.3, 'd': 0.6, 'z': 0.6, 'н': 0.65,
}


def doubled_s(raw, starts_word):
    text = raw.casefold().replace('с', 's')
    at = text.find('ss')
    if at < 0:
        return 0.0
    n = len(text)
    before = text[at - 1] if at else ''
    if n <= 2:
        strength = 5.4 if raw.isupper() else 4.8
        return strength - (1.1 if starts_word else 0.0)
    if n == 3:
        if at == 0:
            return 1.95
        if before == 'a':
            return (2.2 if starts_word else 1.5) if raw.istitle() else 2.7
        if before == 'e':
            return 3.6 if starts_word else 4.6
        return 3.8
    if text.endswith('ness'):
        return 0.7 if n <= 5 else 0.2
    if n == 4:
        value = 1.4 if before == 'e' else 1.8
        return value + 0.5 * raw.istitle() - 0.25 * starts_word
    if n == 5:
        return 1.9 if at <= 1 and before == 'e' else 0.75
    if n == 6:
        if at >= 4:
            return 0.15
        if before == 'a':
            return 0.43
        return 0.6 if starts_word else 1.4
    if before == 'u':
        return 1.19
    return 0.37 if before == 'i' else 0.16


def token_signal(token):
    raw = token.strip()
    text = raw.casefold()
    value = doubled_s(raw, bool(token[:1].isspace()))
    if 'ß' in raw.lower():
        value = 3.7 if len(raw) <= 2 else (1.7 if len(raw) <= 3 else 1.0)
    if len(text) >= 2 and text[-1] == text[-2]:
        letter = text[-1]
        strength = PAIR_STRENGTH.get(letter, 0.0)
        before = text[-3] if len(text) >= 3 else ''
        if letter == 't':
            strength = 1.0 if len(text) == 2 else (0.45 if before == 'a' else 0.7)
        elif letter == 'r' and before:
            strength = 0.9 if before == 'e' else (0.0 if before == 'a' else 0.5)
        elif letter == 'f' and (before == 'o' or len(text) >= 5):
            strength = 0.0
        elif letter == 'c' and before and before in 'ao':
            strength = 0.1
        elif letter == 'd' and len(text) > 2:
            strength = 0.5 if before == 'e' else 0.0
        elif letter == 'p' and len(text) == 2:
            strength = 0.85
        value = max(value, strength)
    if 'ッ' in raw:
        value = max(value, 1.65 if len(raw) == 1 else 0.1)
    if 'ّ' in raw:
        value = max(value, 0.46)
    if text.endswith('ash'):
        value = max(value, 0.5)
    if '\\$' in raw:
        value = max(value, 0.68)
    if '[[' in raw:
        value = max(value, 0.18)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, previous_token = (0.0, '')
    if carry is not None and carry[0] == doc:
        previous, previous_token = carry[1:]
    text = token.casefold()
    last_letter = previous_token[-1:].casefold()
    signal = token_signal(token)
    # Recognize double s across a token boundary, and the split suffix n + ess.
    if last_letter == 's' and text.startswith('s'):
        boundary = 0.8 if len(text) <= 3 else 0.2
        signal = max(signal, boundary * (0.65 if token.isupper() else 1.0))
    if last_letter == 'n' and text == 'ess':
        if not previous_token.lstrip()[:1].isupper():
            signal = 2.2
    continuation = bool(token and token[0].isalpha())
    echo = previous * (0.13 if continuation else 0.02)
    return (doc, signal, token), float(signal + echo)

