"""A boundary signal for a space that was tokenized separately.

After a lone ASCII-space token, another space is strongly positive, and a
space-prefixed word is moderately positive. Unprefixed letters and byte
fragments are negative; digits are near zero. NBSP and control characters
give the strongest negative responses. Longer indentation attenuates the
signal; repeated tabs have a smaller negative response. At document start,
a lone space is positive and a lone tab negative. Otherwise predict zero.
"""
import unicodedata

READS = ()

# Current-token responses immediately after a standalone ASCII space.
WHITESPACE_AND_CONTROL = {
    ' ': 0.986,
    '\xa0': -4.64,  # non-breaking space
    '\x00': -3.48,  # NUL
    '\t': -2.81,
    '\r': -1.19,
}


def after_space(s):
    if s in WHITESPACE_AND_CONTROL:
        return WHITESPACE_AND_CONTROL[s]
    if s.startswith(('\t', '\r')):
        return -1.15
    if s.startswith(' ') and s.strip():
        first = s.lstrip()[0]
        if first in "\"'":
            return 0.52
        if first.isalpha():
            return 0.34 if first.isupper() else 0.28
        return 0.17
    if not s or s.isspace() or s.startswith('<'):
        return 0.0
    if s.isascii():
        if s.isdigit():
            return -0.06 if s == '0' else 0.015
        if s[0].isalpha():
            return -2.0
        return -2.1 if len(s) > 1 and len(set(s.strip())) == 1 else 0.0
    if s[0] == '\ufffd':
        return -2.05
    if s.isdigit():
        return 0.0
    name = unicodedata.name(s[0], '')
    if 'ARABIC' in name:
        return -1.67
    if 'LATIN' in name:
        return -1.2
    return -0.99 if 'CJK' in name else -0.6


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else None
    value = 0.0
    if prev is None:
        value = 1.273 if s == ' ' else -0.64 if s == '\t' else 0.0
    elif prev and not prev.strip(' '):
        n = len(prev)
        if n > 1 and s == ' ':
            value = 0.076 if n == 2 else -0.05
        else:
            value = after_space(s) / (n * n)
    elif s == '\t' and prev and not prev.strip('\t'):
        value = -0.46
    return (doc, s), float(value)

