"""A local spelling-based approximation to coordination/list separators.

And/or and commas respond more positively after symbols, short fragments, and
number words than after long lowercase word tokens. Noun-like endings reduce
the response; capitalization and -ly increase it. Semicolons and logical/list
operators have weaker related responses. Some non-English conjunctions are
also covered. All other tokens predict zero. Only the preceding token is kept,
and it is forgotten at document boundaries; this is not a grammatical parser.
"""
from math import log1p

READS = ()
NUMBER_WORDS = frozenset("""
zero one two three four five six seven eight nine ten eleven twelve hundred
thousand million billion first second third fourth fifth
""".split())

def context_scores(previous):
    word = previous.strip()
    lower = word.lower()
    letters = sum(c.isalpha() for c in word)
    whole_lower = previous.startswith(" ") and word.islower()
    number_word = lower in NUMBER_WORDS
    noun_ending = lower.endswith(
        ("tion", "sion", "ment", "ness", "ity", "ance", "ence", "ism")
    )
    coordination = (
        2.411 - 1.071 * log1p(letters) + 0.052 * min(letters, 12)
        + 0.196 * (letters == 1) + 0.224 * any(c.isupper() for c in word)
        - 0.511 * whole_lower - 0.381 * lower.endswith("s")
        - 0.333 * lower.endswith("ing") + 0.296 * lower.endswith("ly")
        + 0.029 * lower.endswith("ed") - 0.536 * noun_ending
        + 1.075 * number_word
    )
    comma = (
        -0.376 + 0.421 * coordination + 0.122 * whole_lower
        - 0.189 * (not word.isascii()) - 0.189 * number_word
        + 0.06 * lower.endswith("ed")
    )
    if not letters:
        comma, coordination = 0.74, 2.25
        if "," in word:
            coordination = 0.33 if previous == "," else 1.25
        elif any(c in ")]}" for c in word):
            coordination = 2.56
        elif word == ";":
            coordination = 1.44
        elif word in {"–", "—"}:
            coordination = 1.2
        elif word in {".", "”"}:
            coordination = 1.95
    return coordination, comma, letters


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    word = token.strip()
    coordination, comma, letters = context_scores(previous)
    value = 0.0
    if token in {" and", " or"}:
        value = coordination
    elif word == "and":
        value = 0.52 + 0.19 * coordination + 0.96 * comma
    elif word == "or":
        value = 0.09 + 1.5 * comma
    elif word in {"And", "AND", "Or", "OR", "-and", "_and", "/or", "_or"}:
        value = 1.15 if word.lower() == "and" else 1.35
    elif token == ",":
        value = comma
    elif token == " ,":
        value = 0.45
    elif word in {",", ";"}:
        value = 0.45 * comma - 0.1
    elif word == "/":
        value = -0.45 + 0.41 * coordination - 0.53 * comma
    elif word == "&":
        value = -0.28 + 0.42 * coordination
    elif word in {"&&", "||"}:
        value = 0.3 + 0.4 * comma
    elif word == "，":
        value = 0.52 if letters == 0 else 0.11 if letters == 1 else -0.19
    elif word == "、":
        value = 1.21 if letters == 0 else 0.66 if letters == 1 else 0.21
    elif word in {"和", "与", "與", "及", "或"}:
        value = 1.4 if letters == 0 else 0.85 if letters == 1 else -0.1
    elif word in {"und", "oder"}:
        value = 0.38 + 0.45 * coordination - 0.36 * comma
    elif word in {"или", "و", "ve", "dan", "és", "と", "や"}:
        value = 0.6
    elif word in {"và", "eller", "와", "과", "または"}:
        value = 1.0
    elif word in {"и", "et"}:
        value = 0.13
    elif word.lower() == "alternatively":
        value = 0.75
    return (doc, token), float(value)

