programs.sol:
"""A lexical personal-reference signal, especially first-person pronouns.

English I/me/my/we/us/our and Chinese 我 give positive signals. Chinese
我-containing phrases are weaker than 我 alone; several other languages' personal
forms and a secondary response to China are included. Spacing, case and the
preceding grammatical cue modify the strength. Selected English non-first-person
forms and auxiliary contractions have small negative responses; most tokens
predict zero. The previous-token state resets at document boundaries.

This models spellings, not who a pronoun refers to: names and code can also fire.
Strengths are fitted training averages. Miscellaneous weak lexical effects and
longer-range context are deliberately left out to keep the explanation local.
"""
READS = ()

# English: space-prefixed, bare lowercase, capitalized.
ENGLISH = {
    'I': (0.98, 1.08, 1.08), 'me': (1.20, 0.40, 1.02),
    'my': (0.83, 0.60, 1.05), 'we': (0.50, 0.42, 0.77),
    'us': (1.10, 0.04, 0.63), 'our': (0.69, 0.01, 0.84),
    'ours': (0.85, 0.0, 0.85), 'mine': (0.13, 0.13, 0.13),
    'myself': (0.85, 0.85, 0.85), 'ourselves': (0.65, 0.65, 0.65),
}
# Some common first-person translations and possessive inflections.
FIRST_PERSON = {
    'я': 0.70, 'мы': 0.30, 'меня': 1.28, 'мне': 1.40,
    'нас': 0.65, 'нам': 0.75, 'наш': 0.52, 'наших': 0.65,
    'нашем': 0.90, 'мой': 1.05,
    'ich': 0.75, 'wir': 0.49, 'mich': 0.34, 'mein': 0.56,
    'meine': 0.80, 'meiner': 0.80, 'meinen': 0.98, 'unser': 0.4,
    'unsere': 0.57, 'nous': 0.69, 'notre': 0.57, 'moi': 0.52,
    'tôi': 1.62, 'mình': 0.78, 'saya': 1.44, 'kita': 0.96,
    'kami': 1.12, '우리': 2.85, '내가': 1.83, '나': 0.60,
    '저': 0.90, '저희': 1.7, '내': 0.30, 'เรา': 1.75,
}
ASIAN_REFERENCE = {
    '自己': 0.8, '本人': 0.8, '大家': 0.8, '们': 1.0, '們': 1.0,
    '私': 0.7, '私は': 1.4, '私も': 1.4, '私が': 2.0, '私の': 2.4,
    'わたし': 2.0, '私たち': 2.0, '俺': 2.4, '吾': 2.4, '朕': 2.0,
    '自我': 1.9, '让我': 1.9, '讓我': 1.9,
    '中国': 1.78, '中國': 1.20,  # A secondary response to China.
}


def asian_value(text):
    if text in ASIAN_REFERENCE:
        return ASIAN_REFERENCE[text]
    if '我' in text:
        if text == '我':
            return 5.0
        if text in ('我们', '我們', '我的'):
            return 3.0
        if text.startswith(('让', '讓', '帮', '幫')):
            return 1.4
        return max(1.0, 2.7 - 0.6 * (len(text) - 2))
    if text in ('咱', '咱们', '咱們'):
        return 2.5
    if text not in ('其他', '其它'):
        for pronoun, level in [('你', 1.55), ('您', 1.37), ('他', 1.22),
                               ('她', 1.26), ('它', 1.19)]:
            if pronoun in text:
                if text in (pronoun + '们', pronoun + '們'):
                    return 1.9 if pronoun == '你' else 1.1
                return level if text == pronoun else 0.9
    return None


def step(carry, prefix, upstream):
    raw, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text, completed = raw.strip(), False
    # Decode only byte fragments, including the token completing a pronoun.
    if '\ufffd' in raw:
        old = prefix.text_prefixes[-2] if prefix.position else ''
        text = prefix.text_prefixes[-1][len(old.rstrip('\ufffd')):].strip()
        completed = bool(text and '\ufffd' not in text)
    word = text.lstrip('"“‘(…./-:<>,')
    key = 'I' if word == 'I' else word.lower()
    value = asian_value(text)
    if value is not None:
        value *= 1.25 if completed and len(text) == 1 else 1.0
    elif key in ENGLISH:
        spaced, bare, capitalized = ENGLISH[key]
        value = capitalized if word.istitle() else (
            spaced if raw.startswith(' ') or word != text else bare)
        if key == 'I':
            value = spaced if raw.startswith(' ') else bare
            if raw == 'I' and previous and previous[-1].isalpha():
                value = 0.0 if previous.strip().isupper() else 0.25
            elif text != word and text[0] in './-:<>':
                value = 0.55
        elif key == 'us' and word.isupper():
            value = 0.12
    elif key in FIRST_PERSON:
        value = FIRST_PERSON[key]
        if key == 'ich' and word.istitle():
            value = 1.15
        if not raw.startswith(' ') and word.islower():
            value *= 0.18
    elif word in ("'m", "'re", "'ve"):
        value = -0.15
    elif key == 'your':
        value = -0.18
    elif key in ('he', 'she', 'his', 'her', 'they', 'it'):
        value = -0.09 if word.islower() and raw.startswith(' ') else 0.0
    else:
        value = 0.0
    prev_word = previous.strip().lower()
    if raw in (' I', ' we'):
        if prev_word in ('if', 'maybe', 'perhaps', 'can', 'could', 'do', 'did'):
            value -= 0.4 if key == 'I' else 0.25
        elif prev_word in ('.', '!', '?', ','):
            value += 0.2 if key == 'I' else 0.05
    if raw in (' me', ' us'):
        if prev_word in ('for', 'to', 'with', 'of', 'in', 'on', 'at', 'by', 'from'):
            value = 1.48
        elif prev_word == 'let':
            value = 1.10 if key == 'me' else 0.82
    return (doc, raw), float(value)

