"""Approximate a self-reference feature: first-person tokens are its clearest triggers."""

READS = ()

PUNCTUATION = ".,!?;:'\"()[]{}<>，。！？、:;“”‘’"
SINGULAR = {"me", "my", "myself"}
PLURAL = {"we", "us", "our", "ours", "ourselves"}
OTHER_FIRST_PERSON = {"nous", "ich", "я", "мы", "내", "저", "우리"}
THIRD_PERSON = {"he", "she", "they", "her", "it", "your"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(PUNCTUATION)

    if word == "�" and prefix.text_prefixes[-1].endswith("我"):
        value = 4.8
    elif word == "我":
        value = 4.8
    elif word.startswith("我"):
        value = 2.9
    elif word.startswith(("你", "您")):
        value = 1.4
    elif word.startswith(("他", "她", "它")):
        value = 1.0
    elif word == "tôi":
        value = 1.7
    elif word == "I":
        value = 0.95
    elif word in {"My", "We", "Our", "Me"}:
