programs.sol:
"""Respond to nonzero digits after zero, and more weakly after five.

Digit response rises from 1 through 5, then saturates. Repeated zeros
strengthen it; a decimal point or another short separator weakens it.
The response is stronger at the document's first digit pair.
Leaving a zero for punctuation or ordinary text gives a negative response.
"""
READS = ()

# A separator can bridge zero to the next digit, but reduces the response.
ZERO_BRIDGES = {'.': 0.28, ',': 0.20, '-': 0.15, ' ': 0.28,
                ':': 0.09, '/': 0.06, 'x': 0.16, '\\x': 0.28}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before, zero_run, position = '', '', 0, 0
    else:
        _, previous, before, zero_run, position = carry
        position += 1

    value = 0.0
    if len(token) == 1 and token in '123456789':
        d = min(int(token), 5)
        response = 1.43 + 0.98*d - 0.082*d*d
        if previous == '0':
            value = response * (1.2 if position == 1 else 1.0)
            if zero_run >= 2:
                value += 0.15 + 0.26*d - 0.025*d*d
        elif previous == '5':
            small = min(d, 4)
            value = 0.28 + 0.21*small - 0.026*small*small
        elif before == '0':
            value = response * ZERO_BRIDGES.get(previous, 0.0)
        elif previous in {'O', 'o', ' O', ' o'}:
            value = response * 0.25
        elif previous.endswith('O'):
            value = response * 0.13
    elif previous == '0' and token != '0':
        if token in {'-', '/', '+', 'th', '年'}:
            value = -0.75
        elif token in {' ', 'x'}:
            value = -0.50
        elif token.isspace():
            value = -0.15 if '\n' in token else -0.18
        elif token == ',':
            value = -0.36
        elif token.strip():
            value = -0.27

    run = zero_run + 1 if token == '0' else 0
    return (doc, token, previous, run, position), float(value)

programs.luna:
"""Spot a nonzero digit emerging from a zero in a written number.

The component's strongest responses in the sampled examples occur when a
number moves past zeros, as in 2006, 0.05, or an identifier like 205. Track
only the number's recent character-level shape; predict a positive pulse at
that transition and nothing on ordinary text.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    open_number, last_zero, old_doc = carry or (False, False, doc)
    if doc != old_doc:
        open_number, last_zero = False, False

    pulse = False
    for char in prefix.token_strings[-1]:
        if char.isdigit():
            if char != "0" and open_number and last_zero:
                pulse = True
            open_number = True
            last_zero = char == "0"
        elif char in ".," and open_number:
            pass
        else:
            open_number, last_zero = False, False

    return (open_number, last_zero, doc), float(2.5 if pulse else 0.0)

programs.sol:
"""A partial approximation of the observed collocation-completion response.

The strongest case is a common Chinese word split after its space-led first
character. Recognized grammatical, predicate, and noun completions get a
negative contribution. A few familiar English expressions and programming
conventions behave similarly. Unrecognized Chinese continuations get a smaller negative value;
elsewhere the baseline is near zero.
UTF-8 fragments are skipped until a complete continuation can be recognized.
Most token-specific background variation is deliberately left unmodeled.
"""
READS = ()

CHINESE_GRAMMATICAL_WORDS = set("""
然后 然後 因此 如何 其中 同时 其实 首先 现在 这里
我们 我們 这个 最初 最后 因为 所以 或者 自己 对于 那么
最近
""".split())
CHINESE_PREDICATES = set("""
可以 建议 欢迎 支持 知道 开始 打开 回答 必须 进行 满足 抱歉
按照 可能 增加 需要 根据 研究 发表 特别 免费
提供 联系 表示 建立 继续 发展 阅读 发现 喜欢 帮助
""".split())
CHINESE_NOUNS = set("""
公司 地址 客户 故事 技术 教育 智能 内容 国家 类型 主页
模型 地区 环境 软件 命令 对象 协议 视频 政府 游戏 妈妈 媽媽
""".split())
# Beijing, Shanghai, and Hong Kong.
CHINESE_PLACES = {'北京', '上海', '香港'}

# Familiar English expressions and a country name:
# the rule fires only at the last token of the expression.
PHRASES = (
    ('other hand', -0.30),
    ('united states', -0.13),
    ('at least', -0.085),
    ('this case', -0.105),
    ('other words', -0.14),
    ('make sure', -0.065),
    ('not only', -0.065),
    ('this morning', -0.215),
    ('next morning', -0.25),
    ('as follows', -0.085),
    ('as well as', -0.05),
    ('a number', 0.08),
    ('a variety', 0.08),
    ('the same', 0.03),
)


def han(s):
    return bool(s) and all('\u3400' <= c <= '\u9fff' for c in s)


def ends_phrase(text, phrase):
    return text.endswith(phrase) and (
        len(text) == len(phrase) or not text[-len(phrase)-1].isalnum())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, tail = False, ''
    else:
        _, pending, tail = carry
    s = prefix.token_strings[-1]
    complete = han(s)
    partial = '\ufffd' in s
    value = -0.023 if complete else -0.004

    if pending and complete:
        # Decode the fragments only on this rare candidate position.
        text = prefix.text_prefixes[-1]
        previous = text[:-len(s)]
        if len(previous) >= 2 and previous[-2] == ' ' and han(previous[-1]):
            word = previous[-1] + s[0]
            value = -0.052
            if word in {'首先', '然后', '然後'}:
                value = -0.95
            elif word in CHINESE_GRAMMATICAL_WORDS:
                value = -0.70
            elif word in CHINESE_PREDICATES:
                value = -0.56
            elif word in CHINESE_NOUNS:
                value = -0.50
            elif word in CHINESE_PLACES:
                value = -0.77

    new_tail = (tail + s)[-48:]
    lower, old_lower = new_tail.lower(), tail.lower()
    for phrase, prediction in PHRASES:
        if ends_phrase(lower, phrase) and not ends_phrase(old_lower, phrase):
            value = prediction
            break

    # URL syntax, common type/package notation, and directional suffixes.
    if s == '://' and tail.lower().endswith(('http', 'https')):
        value = -0.115 if tail.lower().endswith('https') else -0.185
    elif s == '_modules' and tail.endswith('node'):
        value = -0.09
    elif s == 'ern' and tail.lower().endswith('-east'):
        value = -0.48
    elif s == 'ern' and tail.lower().endswith('-west'):
        value = -0.11
    elif s.strip() == 'nil' and tail.endswith(('!=', '==')):
        value = -0.14
    elif s.startswith('{}') and tail.endswith('interface'):
        value = -0.25
    elif s == '<tool_response>':
        value = -0.116
    elif s == '<tool_call>':
        value = -0.05
    elif s == '<think>':
        value = 0.04
    elif s == '</think>':
        value = 0.094
    elif s == '<|im_start|>':
        value = -0.014
    elif s in {'<|im_end|>', '</tool_call>'}:
        value = 0.013

    if s.startswith(' ') and (han(s[1:]) or partial):
        pending = True
    elif not (pending and partial):
        pending = False
    return (doc, pending, new_tail), float(value)

programs.haiku:
"""Layer 0, MLP down-projection, component 240 (Qwen3-1.7B).

What it does: a weak, mostly-negative feature of the current token's identity.
It is most negative on Chinese characters, strongest on a Chinese character that
directly follows a garbled (U+FFFD, broken UTF-8) byte fragment, and mildly
negative on code identifiers and non-Latin scripts. Ordinary English words and
digits sit near zero. Its big spikes (about -0.6 to -0.9) are rare; the typical
value is a few hundredths.

Predicts one value per token from the token's character class and whether the
previous token (in the same document) was a garbled fragment. Values are the
class means measured on training rows.
"""
import re

READS = ()

CODE_IDENT = re.compile(r"[a-z][A-Z]|[._][A-Za-z]")
ENGLISH_WORD = re.compile(r" ?[A-Za-z]+")


def _is_cjk(s):
    return any("一" <= c <= "鿿" for c in s)


def _is_other_script(s):
    return any("぀" <= c <= "ヿ" or "Ѐ" <= c <= "ӿ" or "฀" <= c <= "๿" for c in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    garbled_prev = "�" in prev
    if "�" in s and len(s.strip()) <= 1:
        value = -0.0051
    elif _is_cjk(s):
        value = -0.0487 if garbled_prev else -0.0231
    elif _is_other_script(s):
        value = -0.0071
    elif CODE_IDENT.search(s):
        value = -0.0118
    elif ENGLISH_WORD.fullmatch(s):
        value = -0.0052
    elif s.strip() == "" or any(c.isdigit() for c in s):
        value = -0.0005
    else:
        value = -0.0027
    return carry, float(value)

