"""Negative responses to sending, delivery, and transport vocabulary.

送 is strongest, with weaker responses to its compounds and English
word families. Sentence/sentiment spellings also trigger. Recent kana
and dispatch/broadcast prefixes adjust standalone 送. A weak response
can continue onto selected articles, prepositions, or 了/到了. Split
smugg-led and byte-split 송 are recognized too. State resets between
documents. Other tokens are zero: small, idiosyncratic lexical responses
are deliberately left unexplained.
"""
READS = ()

FAMILIES = (
    (-1.85, 'send'),
    (-1.60, 'sent sends sending'),
    (-1.10, 'sender senders'),
    (-0.85, 'transport transports transported transporting transportation '
            'deliver delivers delivered delivering delivery'),
    (-0.70, 'transfer transfers transferred transferring '
            'shipped shipping shipment shipments conveyor conveying'),
    (-1.00, 'escort escorts escorted escorting smugg smuggling'),
    (-0.85, 'sentence sentenced sentencing'),
    (-0.65, 'sentences sentient subparagraph 句子'),
    (-0.35, 'sentiment sentiments sentimental gift gifts gifted award awarded '
            'donate donated donation furnish furnished'),
    (-0.75, 'courier プレゼント 奉 奉献 enviar entrega transporte'),
    (-1.35, 'đưa'),
    (-1.00, '运输 運輸 传输 傳輸 输'),
    (-0.50, '发 發 輸 运 運 返回 搬 投稿 往 供给 '
            '传递 提交 交付 发放'),
)
FAMILIES = tuple((value, frozenset(words.split()))
                 for value, words in FAMILIES)


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    recent, previous = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    word = token.strip().strip('.,/()[]{}:;_"\'').lower()
    cue = 0.0
    if word == '送':
        if recent.endswith(('发', '發')):
            cue = -3.3
        elif recent.endswith('放'):
            cue = -5.2
        else:
            japanese = any('\u3040' <= c <= '\u30ff' for c in recent)
            cue = -6.2 if japanese else -7.3
    elif '送' in word:
        cue = -3.5 if word.startswith('送') else -2.8
        if word in {'移送', '运送'}:
            cue = -4.0
        elif word == '送料':
            cue = -1.85
        elif word == '配送':
            cue = -2.2
    elif word in {'赠', '贈'}:
        cue = -2.0
    elif word == '송':
        cue = -3.4
    elif '\ufffd' in token and prefix.text_prefixes[-1].endswith('송'):
        cue = -1.0
    elif word.startswith('отправ'):
        cue = -1.5
    elif word == 'led' and recent.lower().endswith('smugg'):
        cue = -1.1
    else:
        for value, family in FAMILIES:
            if word in family:
                cue = value
                break
    value = cue
    if previous < -0.3:
        if token == ' of':
            value += 0.6 * previous
        elif token in {' a', ' an', ' the'}:
            value += 0.14 * previous
        elif token in {' to', ' by', ' from', ' via'}:
            value += 0.07 * previous
        elif previous < -1.0 and token in {'了', '到了'}:
            value += 0.15 * previous
    return (doc, (recent + token)[-128:], cue), value

