from functools import lru_cache
import unicodedata as ud

READS: tuple[str, ...] = ()
VOWELS = frozenset('aeiouy')
TONES = frozenset('\u0300\u0301\u0303\u0309\u0323')
ONSETS = frozenset('''
b c ch d g gh h k kh l m n ng ngh nh p ph q qu r s t th tr v x
'''.split())
CODAS = frozenset('m n ng nh t p c ch'.split())
FUNCTION_WORDS = frozenset('''
và là của các những một được không để nhưng sẽ hoặc trên đến với cho từ
người cũng này đó có khi con
'''.split())
