def spelling(raw):
    word = raw.strip().lower()
    nfd = ud.normalize('NFD', word)
    plain = ''.join(c for c in nfd if not ud.combining(c)).replace('đ', 'd')
    latin = bool(word) and all('LATIN' in ud.name(c, '') for c in word)
    # Horn vowels and Vietnamese stacked-tone vowels are distinctive cues.
    marked = any(c in 'ơư' or '\u1ea0' <= c <= '\u1ef9' for c in word)
    tone = any(c in TONES for c in nfd)
    first_vowel = next(
        (i for i, c in enumerate(plain) if c in VOWELS), len(plain)
    )
    onset = plain[:first_vowel]
    return Spelling(word, plain, latin, marked, tone, onset)


