    if recent and now.latin and spaced:
        if p in ONSETS:
            value += 0.39
        elif size <= 3 and now.word.isascii() and not vowel_start:
            value += 0.40
        if p in {'qu', 'tr', 'th'}:
            value += 0.53
        if size <= 3 and now.word.isascii():
            if now.onset in {'c', 'g', 'q'}:
                value += 0.18
            elif now.onset == 'v':
                value += 0.29
        if not vowel_start and not now.word.isascii():
            value += 0.15
        if now.word in FUNCTION_WORDS:
            value -= 0.22
        if vowel_start:
            value += 0.09
        if old.plain.endswith(('m', 'n', 'ng', 'nh')):
            value += 0.09
