    r'\b(let|prove|theorem|lemma|equation|vector|integer|polynomial|'
    r'dimension|subgroup|derivative|matrix|integral|fraction|'
    r'coefficient|rational|variable|function|formula|solution|'
    r'finite|infinite|linear|quadratic|algebra|geometry)\b', re.I)
