"""layers.0.mlp.down_proj:245 - a "markdown code / LaTeX math opener" detector.

The component fires on the delimiter tokens that open or mark inline code and inline math
in text, and is near zero everywhere else:

- a backtick that starts a code span (" `", the most common) is strongest; a bare "`"
  is weaker; backtick runs ("``", "```") and backticks glued to punctuation ("`,", "`\\n")
  are weak.
- a space-prefixed dollar sign that opens inline LaTeX math in prose ("let $x$",
  "for all $n$", "of $G$") is strong; a dollar after a word that means money ("at $5",
  "than $10") is weak; a dollar in code (PHP "$var", shell "${x}", "($x") is zero.
- LaTeX openers " \\(" and " $$" are moderate.

Everything else predicts 0. The program reads only the newest token and the one before it
(the word that precedes a dollar sign), so it is causal."""

READS = ()

# Words that, just before a dollar sign, usually start inline math in prose.
MATH_LEAD_IN = {"that", "all", "let", "for", "in", "with", "on", "and", "of", "is", "to",
                "where", "if", "set"}
# Words that, just before a dollar sign, usually mean a price.
MONEY_LEAD_IN = {"at", "than", "over", "from", "about", "by", ","}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""

    if "`" in token:
        if token == " `":
            return None, 1.9  # opens a markdown code span
        if token == "`":
            return None, 1.3
        if token.startswith("`") or token in (" ``", "``", "```"):
            return None, 0.3  # backtick runs and backticks glued to punctuation
        return None, 1.1  # a backtick after punctuation, e.g. ")`"

    if token in (" \\(", " $$"):
        return None, 0.7  # LaTeX display or \( openers

    if "$" in token:
        if not token.startswith(" ") or token.endswith("{"):
            return None, 0.0  # attached dollars, and ${var} or $ in code
        if previous in MATH_LEAD_IN:
            return None, 1.3  # inline math in prose
        if previous in MONEY_LEAD_IN:
            return None, 0.4  # a price
        if previous.isalpha():
            return None, 0.9
        return None, 0.0  # after code punctuation such as "=" or "("

    return None, 0.0

