a/o continuations are positive and i/y continuations negative. The response
weakens for longer fragments, especially a long preceding fragment or a vowel
before its e. Latin spaces and title-case word starts suppress it. The i-t/i-z
continuations are particularly negative. Accents are ignored in Latin text.
The same e-to-vowel junction is recognized in Cyrillic, Greek, Japanese kana
and Thai spelling, with script-specific strengths. A short text carry joins
Thai e signs to consonants when they occupy separate tokens.
"""
import math
import unicodedata

READS = ()
# Single-letter strength, short-fragment strength, length decay.
VOWEL_RESPONSE = {
    'a': (2.05, 2.21, 0.775),
    'i': (-1.81, -2.51, 0.796),
    'o': (1.64, 1.72, 0.748),
    'u': (0.18, 0.45, 0.852),
    'y': (-1.00, -1.08, 0.720),
    'e': (-0.05, -0.19, 0.718),
}


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c) or '\u0e00' <= c <= '\u0e7f')


# Vowel letters in Cyrillic and Greek: signed junction strengths.
CYRILLIC_VOWELS = {
    'а': 2.1, 'о': 1.4, 'у': 0.3,
    'и': -0.75, 'ы': -0.7, 'я': -0.5, 'ю': 0.2,
}
GREEK_VOWELS = {
    'α': 2.5, 'ο': 2.0, 'ω': 1.3, 'ι': -0.83, 'υ': 0.2,
}
E_KANA = frozenset('えけげせぜてでねへべぺめれゑエケゲセゼテデネヘベペメレェ')


def thai_junction(token):
    # Thai writes the e sign before the consonant; a following i vowel sign
    # reverses this signal. Long i gliding into y is less negative.
    if token.startswith('ิ'):
        strength = -4.1 if len(token) == 1 or token.endswith('น') else -1.7
        return strength * 0.8**max(len(token)-2, 0)
    if token.startswith('ี'):
        return -3.0 if set(token) <= set('ี้่๊๋') else -0.9
    if token.startswith('ื'):
        if token == 'ือ':
            return 0.2
        return -0.4 if token == 'ื' else -0.9
    if token.startswith('้น'):
        return 1.9
    if token.startswith('้'):
        return 0.9
    if token.startswith('่า'):
        return 0.6
    if token.startswith('าะ'):
        return -0.6
    if token.startswith(('า', 'อ')):
        return 1.4
    return 0.0


def junction(previous, raw, thai_context=""):
    token = plain(raw)
    if not previous or not token:
        return 0.0
    if previous.endswith(('е', 'э')) and token[0] in CYRILLIC_VOWELS:
        return CYRILLIC_VOWELS[token[0]] * 0.94**max(len(token)-2, 0)
    if previous.endswith('ε'):
        if token[0] in GREEK_VOWELS:
            strength = GREEK_VOWELS[token[0]]
            if token[0] == 'ι' and plain(raw) != raw.lower():
                strength *= 0.5
            return strength * 0.9**max(len(token)-1, 0)
    if previous[-1] in E_KANA:
        if token.startswith(('い', 'イ')):
            strength = -1.1 if token[0] == 'イ' else -0.45
            return strength * (1.3 if len(token) > 1 else 1)
        if token.startswith(('あ', 'ア')):
            return 0.8 if token[0] == 'ア' else 0.15
    thai_context = thai_context or previous
    e_sign = thai_context.rfind('เ')
    if e_sign >= 0 and all('ก' <= c <= 'ฮ' for c in thai_context[e_sign+1:]):
        return thai_junction(token)
    if not previous.endswith('e') or token[0] not in VOWEL_RESPONSE:
        return 0.0
    if len(token) > 1 and raw.istitle():
        return 0.0
    single, pair, decay = VOWEL_RESPONSE[token[0]]
    strength = single if len(token) == 1 else pair * decay**(len(token)-2)
    if token.startswith(('it', 'iz')):
        strength *= 1.535
    length = len(previous.strip())
    gate = math.exp(-0.168 * max(length - 3, 0))
    if length == 1:
        gate *= 1.11
    if previous[-2:-1] in ('a', 'e', 'i', 'o', 'u', 'y'):
        gate *= 0.776
    return strength * gate


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    value = -0.003
    thai_context = ''
    if carry is not None and carry[0] == doc:
        thai_context = carry[2]
        value += junction(carry[1], raw, thai_context)
    # The e sign can be split from its Thai consonant cluster by tokenization.
    thai_context = (thai_context + raw)[-12:]
    return (doc, plain(raw), thai_context), float(value)

"""A mostly orthographic detector for short 'ort' spellings.

It predicts large negative activations for ort/sort/fort/tort, less for
longer forms, ports and courts. Sorting-method names strengthen 'sort';
'some/any sort' and split 'effort'/'cohort' weaken it. Smaller negative
responses cover kind/kinds, Chinese 'sorting', and Cyrillic ort/port.
Other tokens predict zero.
The recent-text buffer resets whenever the document changes.
"""
import re

READS = ()
SORT_ALGORITHM = re.compile(
    r'(?:bubble|selection|insertion|quick|merge|heap|shell|radix)'
    r'[ _]*sort$', re.IGNORECASE,
)


def lexical(token):
    word = token.strip().lstrip("_.('`\"/:-")
    w = word.lower()
    if w.startswith('sort'):
        ending = w[4:]
        value = {
            '': -5.6,
            's': -4.3,
            'ing': -3.9,
            'ed': -2.4,
            'e': -2.8,
            'er': -2.8,
        }.get(ending, -1.0)
        if not ending and word == 'Sort' and not token[:1].isspace():
            value = -6.4
        if not ending and token.startswith('.') and word == 'Sort':
            value = -4.5
        if not ending and token.startswith('-'):
            value = -4.3
        if not ending and token.startswith('_') and word.isupper():
            value = -4.0
        return value
    if w.startswith('fortunat') or w in ('orthy', 'orthand'):
        return 0.0
    if w.startswith('fort'):
        if w == 'fort':
            return -4.6 if token.startswith(' f') else -5.0
        return {
            's': -3.5,
            'e': -1.6,
            'h': -0.4,
        }.get(w[4:], -1.2)
    if w.startswith('tort'):
        return -4.1 if w == 'tort' else -1.6
    if w.startswith('ort'):
        if w == 'ort':
            if token[:1].isspace():
                return -1.6 if word == 'Ort' else -3.3
            return -5.3
        return {
            's': -3.8,
            'ed': -3.8,
            'a': -3.8,
            'e': -2.6,
            'ing': -2.6,
            'ic': -2.6,
        }.get(w[3:], -1.3)
    if w in ('mort', 'cort', 'kort', 'hort') or w == 'cortical':
        return -3.0
    if w.startswith(('mort', 'cort')) or w in ('wort', 'dort'):
        return -1.3
    if w == 'port':
        return -0.6 if token.startswith(' p') else -1.1
    if w.startswith('port') and not w.startswith(('portal', 'portfolio')):
        return -0.7
    if w.startswith('court') or w == 'ourt':
        return -0.55 if w.endswith('s') else -1.2
    if w in ('abort', 'aborted') or w.startswith(('resort', 'escort', 'comfort')):
        return -1.0
    if w == 'орт' or w == '排序':
        return -2.7
    if w == 'порт' or w in ('kind', 'kinds'):
        return -0.8 if w != 'kinds' else -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    w = token.strip().lstrip("_.('`\"/:-").lower()
    value = lexical(token)
    if w in ('sort', 'ort') and SORT_ALGORITHM.search(past + token):
        value = -9.2
    elif w == 'sort' and re.search(r'\b(?:some|any)\s*$', past, re.I):
        value = -4.4
    if w == 'ort' and past.lower().endswith('eff'):
        value = -1.9
    if w == 'orts' and past.endswith('Eff'):
        value = -1.1
    if w == 'ort' and past.lower().endswith('coh'):
        value = -2.7
    return (doc, (past + token)[-48:]), value

programs.luna:
"""A small spelling cue: 'ort' (and 'ourt') tokens tend to lower the feature."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower().strip()

    if "ort" in token:
        if token == "ort" or token.endswith("ort"):
            return None, -0.6
        return None, -0.15
    if "ourt" in token:
        return None, -0.15
    return None, 0.0

programs.sol:
"""Local possession, existence, and absence.

HAVE, WITH, and existential THERE + BE license strong negative responses
at 'no' and weaker ones at other quantity words. We also distinguish
'have to', perfect-tense modifiers, pronouns, and identifier suffixes.
Capitalized complements are positive too. Chinese possession/absence
markers usually give a positive response at the next Han token, more
strongly for a single character. These are rounded training averages, not a full
account of the token-specific variation. Remember six tokens per document.
"""
READS: tuple[str, ...] = ()

HAVE = {'have': -4.1, 'has': -4.65, 'had': -3.72, 'having': -3.65,
        "'ve": -2.0, '’ve': -2.0}
BE = {'is', 'are', 'was', 'were', 'be', 'been', 'being', "'s", '’s', '`s'}
ADVERBS = {'currently', 'absolutely', 'virtually', 'probably', 'now',
           'also', 'simply', 'really', 'hardly', 'almost', 'likely',
           'still', 'practically', 'actually', 'certainly', 'usually',
           'seemingly', 'perhaps', 'presently', 'technically', 'just'}
THERE_AUX = {'is': -0.26, 'are': -0.77, 'was': -0.59, 'were': -0.93,
             'have': -1.7, 'has': -1.8, 'had': -1.4,
             'might': -1.0, 'must': -1.05, 'may': -0.88}

# Complement classes: value after HAVE/existence, then WITH/WITHOUT.
PROFILE = (
    ({'many', 'enough', 'little', 'few', 'fewer'}, -1.3, -1.0),
    ({'some', 'several', 'multiple', 'numerous'}, -0.7, -0.45),
    ({'much', 'less', 'only', 'minimal', 'high', 'low', 'higher', 'lower',
      'full', 'great', 'very', 'too', 'sufficient'}, -0.65, -0.65),
    ({'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
      'nine', 'ten', 'both'}, -0.4, -0.4),
    ({'a', 'an', 'the'}, -0.25, -0.12),
    ({'its', 'their', 'his', 'her', 'our', 'your', 'my', 'this', 'that',
      'you', 'it', 'him', 'us', 'me', 'which'}, 0.45, 0.25),
    ({'trouble', 'ease', 'difficulty', 'fun'}, -1.4, -1.4),
    ({'nothing', 'none'}, -1.8, -1.8),
    ({'more'}, -1.25, -0.72),
)
PERFECT = {'not': -0.75, 'had': -1.3, 'already': -1.15, 'yet': -1.15,
           'recently': -1.15, 'never': -0.55, 'always': -0.55,
           'become': 1.0, 'come': 1.0}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1].strip()
    word = (raw.strip('"“”._-—') or raw).lower()
    prev = recent[-1] if recent else ''
    before, fade = recent[:-1], 1.0
    if word in {'no', 'any', 'nothing'}:
        while (prev in ADVERBS or prev == '') and before:
            fade *= 0.75 if prev in {'absolutely', 'hardly', 'almost', ''} else 0.85
            prev, before = before[-1], before[:-1]
    have = prev in HAVE
    exists = prev == 'there' or (prev in BE and 'there' in before[-3:])
    with_word = prev in {'with', 'without'}
    value = 0.0
    if not recent:
        value = -2.2 if word == 'there' else -1.7 if word in HAVE else 0.0
        if word == 'no':
            value = -2.4 if raw == 'no' else -1.45
        elif word in {'with', 'without'}:
            value = -0.8
    elif prev == 'there' and word in THERE_AUX:
        value = THERE_AUX[word]
    elif word == 'no':
        if have:
            value = HAVE[prev] - (3.0 if 'there' in before[-2:] else 0.0)
        elif prev == 'with':
            value = -3.55
        elif exists:
            value = -4.8 if prev == 'there' else -3.0 if prev == 'be' else -4.25
        else:
            value = -1.0 if prev in BE else -0.18
        if raw == 'No':
            value *= 0.1 if prev in {"'s", '’s'} else 0.75
        elif raw == 'NO':
            value *= 0.4
    elif word == 'any':
        value = -2.6 if exists else -1.85 if have else 0.0
        if with_word:
            value = -2.35 if prev == 'without' else -0.95
    elif have or exists or with_word:
        for words, have_value, with_value in PROFILE:
            if word in words:
                value = with_value if with_word else have_value
                break
        if have and word in PERFECT:
            value = PERFECT[word]
        elif have and word == 'to':
            value = -1.3 if prev == 'had' else -1.03 if prev == 'has' else -0.9
        elif not value and raw.isidentifier() and raw[0].isupper():
            value = 0.65
    elif (prev.endswith('有')
          or prev in {'无', '無', '没有', '沒有', '沒', '没'}):
        if raw and all('\u4e00' <= c <= '\u9fff' for c in raw):
            value = 1.2 if len(raw) == 1 else 0.5
            if prev in {'没有', '沒有', '沒', '没'}:
                value = 0.6 if len(raw) == 1 else 0.4
            if word in {'没有', '沒有'}:
                value = -3.0
            elif word in {
                    '无', '無', '了', '了一', '很多', '许多', '許多', '任何'}:
                value = -0.8
            elif word in {'问题', '問題'}:
                value = -1.1
    if raw.startswith(('_', '-')):
        fade *= 0.65
    return (doc, (recent + (word,))[-6:]), float(value * fade)

programs.haiku:
"""Negation and quantity words right after a verb of having, being, existing, or
'with' push this component negative. English ' no' is strongest (about -4 after
'there is', 'have', 'has', 'are', 'with'); ' any', ' many', ' more', ' some',
' enough' are weaker. ' to' and ' not' after have/has/had are mildly negative.
In Chinese the same slot points the other way: a character right after 有 ('have')
or 没有/无 ('without') tends to be positive."""
import re

READS = ()
BE_HAVE = {" is", " are", " was", " were", " has", " have", " had", " been", " be",
           " with", " without", "There", " There", "there", "’s", "'s", "’re", "'re",
           "’ve", "'ve", " absolutely"}
QUANT = {" no": -4.2, " any": -2.0, " nothing": -2.0, " many": -1.0, " some": -0.8,
         " more": -0.8, " enough": -1.0, " fewer": -2.0, " already": -1.0}
HAVE = {" have", " has", " had"}
CHINESE_HAVE = {"有", "没有", "无", "無"}
CJK = re.compile(r"[一-鿿]")

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in QUANT and prev in BE_HAVE:
        return None, QUANT[tok]
    if tok in (" to", " not") and prev in HAVE:
        return None, -1.0
    if tok == " no":
        return None, -0.3
    if prev in CHINESE_HAVE and CJK.search(tok):
        return None, 1.0
    return None, 0.0

programs.luna:
"""Predict a negative response only on English negation and absence words."""
READS = ()
WORDS = {
    "no": -1.0, "not": -0.55, "never": -0.45,
    "neither": -0.45, "none": -0.65, "nothing": -0.5,
    "without": -0.5, "nor": -0.4, "any": -0.8,
}
def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, float(0.53 * WORDS.get(word, 0.0))
